/* Leçons pas à pas d'analyse (HAX103X, Floriane Wozniak, poly de Simon Modeste). CC1 le lundi 23 novembre à 15h, 1 h,
   aucun appareil électronique. Annonce de l'enseignante (forum Moodle, 9 novembre 2026) : les exercices du CC1 seront
   issus des feuilles de TD 1, 2 et 3, associées aux chapitres 1 (les réels), 2 (les suites) et 3 (limites de fonctions).
   Chaque leçon se termine donc par un exercice de ces feuilles, à faire sur papier.
   Forme des anciens CC1 : cours (2 pts), une limite à prouver avec ε (4 pts), une étude de suite (6 pts),
   vrai/faux et tableau inf/min/max/sup (8 pts). */
(function(){
const LES=window.LESSONS=window.LESSONS||{};
const L=(h,x,o)=>Object.assign({k:"learn",h,x},o||{});
const Q=(q,o,a,e,x)=>Object.assign({k:"qcm",q,o,a,e},x||{});
const S=(h,intro,s,x)=>Object.assign({k:"steps",h,intro,s},x||{});
const P=(h,x,sol,check,min,o)=>Object.assign({k:"paper",h,x,sol,check,min},o||{});
const K=(f,b)=>({k:"card",f,b});
const box=s=>`<div class="formula">${s}</div>`;

LES.ana=[
/* ------------------------------------------------------------------ */
{id:"a-quantif",t:"Lire et nier des quantificateurs",min:14,goal:"Comprendre ∀ et ∃, l'ordre des quantificateurs et la négation : la moitié du vrai/faux du CC (8 points).",steps:[
 Q("Comment se lit la phrase « ∀x ∈ ℝ, x² ≥ 0 » ?",["Pour tout réel x, x² est positif ou nul","Il existe un réel x tel que x² ≥ 0","x² ≥ 0 pour un seul x"],0,"∀ se lit « pour tout » et ∃ se lit « il existe ». La phrase se lit donc « pour tout x réel, x² est positif ou nul ». Elle est vraie : un carré n'est jamais négatif."),
 L("∀ et ∃",`<p>Les signes : <b>x ∈ E</b> se lit « x appartient à E » (x est un élément de l'ensemble E) ; P(x) désigne une phrase qui parle de x, comme « x² ≥ 0 » ; <b>P ⇒ Q</b> se lit « si P, alors Q ».</p><ul><li><b>∀x ∈ E, P(x)</b> : « pour tout x de E, P(x) est vraie ». Pour la montrer : on prend un x <b>quelconque</b> (« Soit x ∈ E ») et on prouve P(x). Pour la réfuter : <b>un seul contre-exemple</b> suffit.</li><li><b>∃x ∈ E, P(x)</b> : « il existe (au moins) un x de E tel que P(x) ». Pour la montrer : <b>un seul exemple</b> suffit. Pour la réfuter : il faut montrer que P(x) est fausse pour tous les x.</li></ul><p>Exemple : « ∀x ∈ ℝ, x &gt; 2 ⇒ x &gt; 3 » (pour tout réel x, si x &gt; 2 alors x &gt; 3) est <b>fausse</b> : x = 2,5 est un contre-exemple, car 2,5 &gt; 2 mais 2,5 n'est pas plus grand que 3.</p>`),
 Q("« ∃x ∈ ℝ⁺, x &lt; √x » est-elle vraie ? (ℝ⁺ désigne les réels positifs ou nuls.)",["Oui : x = 1/4 donne 1/4 &lt; 1/2","Non : x = 4 donne 4 &lt; 2, ce qui est faux","Non : x ≥ √x pour tout réel x ≥ 0"],0,"Un seul exemple suffit pour prouver un ∃ : √(1/4) = 1/2, et 1/4 &lt; 1/2. Que x = 4 ne convienne pas ne prouve rien : pour réfuter un ∃, il faudrait que l'inégalité soit fausse pour tous les x. Et « x ≥ √x pour tout x ≥ 0 » est faux, justement à cause de x = 1/4 : c'est vrai seulement pour x = 0 et pour x ≥ 1 (CC1 2024-2025, partie 2, question 1 b)."),
 L("L'ordre compte",`<p>Comparer, pour une suite (uₙ) :</p><ul><li><b>∃c ∈ ℝ, ∀n ∈ ℕ, uₙ ≤ c</b> : <b>un même</b> c marche pour tous les n. C'est « (uₙ) est majorée » : un nombre c est au-dessus de tous les termes. (Avec uₙ ≥ c à la place, un nombre c est en dessous de tous les termes : c'est « (uₙ) est minorée ».)</li><li><b>∀n ∈ ℕ, ∃c ∈ ℝ, uₙ ≤ c</b> : pour chaque n, on peut choisir c (par exemple c = uₙ). C'est vrai pour <b>toutes</b> les suites.</li></ul><p>Règle : dans « ∀… ∃… », ce qui suit le ∃ peut <b>dépendre</b> de ce qui est avant. Dans la définition de la limite, « ∀ε &gt; 0, ∃N » : N dépend de ε.</p>`),
 Q("Quelles suites vérifient « ∀c ∈ ℝ, ∃n ∈ ℕ, uₙ ≤ c » ?",["Les suites non minorées","Toutes les suites","Aucune suite","Les suites majorées"],0,"La phrase dit : quel que soit le réel c, la suite a un terme uₙ ≤ c. Aucun réel m ne peut donc être en dessous de tous les termes : avec c = m − 1, on trouve un terme uₙ ≤ m − 1 &lt; m. La suite n'est pas minorée. Dans l'autre sens, une suite non minorée a bien un terme sous n'importe quel c (TD 2, ex. 3 e). « Toutes les suites » est faux : uₙ = n n'a aucun terme sous c = −1. « Majorée » parle d'un plafond, pas d'un plancher."),
 L("Nier une phrase",`<p>Pour écrire le contraire (la <b>négation</b>), on échange ∀ et ∃, et on nie la fin :</p><ul><li>non(∀x, P(x)) = ∃x, non P(x) ;</li><li>non(∃x, P(x)) = ∀x, non P(x) ;</li><li>non(P ⇒ Q) = P <b>et</b> non Q ;</li><li>non(a &lt; b) = a ≥ b.</li></ul>${box("non( ∀ε &gt; 0, ∃N ∈ ℕ, ∀n ≥ N, |uₙ − ℓ| ≤ ε )  =  ∃ε &gt; 0, ∀N ∈ ℕ, ∃n ≥ N, |uₙ − ℓ| &gt; ε")}<p>La seconde phrase dit « (uₙ) ne tend pas vers ℓ » : il y a un écart ε que la suite dépasse toujours plus loin.</p>`),
 Q("Quelle est la négation de « ∀x ∈ ℝ, x² + x ≥ 0 ⇒ x ≥ 0 » ?",["∃x ∈ ℝ, x² + x ≥ 0 et x &lt; 0","∀x ∈ ℝ, x² + x &lt; 0 ⇒ x &lt; 0","∃x ∈ ℝ, x² + x &lt; 0 et x ≥ 0"],0,"∀ devient ∃, et non(P ⇒ Q) = P et non Q. Cette négation est vraie : x = −2 donne 4 − 2 = 2 ≥ 0 et −2 &lt; 0. La phrase de départ est donc fausse."),
 Q("Quelle est la négation de « ∀A &gt; 0, ∃α &gt; 0, ∀x &gt; α, f(x) &gt; A » ?",["∃A &gt; 0, ∀α &gt; 0, ∃x &gt; α, f(x) ≤ A","∃A &gt; 0, ∃α &gt; 0, ∀x &gt; α, f(x) ≤ A","∀A &gt; 0, ∃α &gt; 0, ∀x &gt; α, f(x) ≤ A"],0,"Chaque ∀ devient ∃, chaque ∃ devient ∀, et on nie la fin : non(f(x) &gt; A) = f(x) ≤ A. Tu retrouveras cette phrase au chapitre 3 : elle dit « f ne tend pas vers +∞ en +∞ » (TD 3, exercice 5)."),
 P("TD 2, exercice 3 : (c), (d) et (f), sur papier",`<p>Quelles sont les suites (uₙ) réelles satisfaisant les assertions suivantes ?</p><p>(c) ∀c ∈ ℝ, ∀n ∈ ℕ, uₙ ≤ c</p><p>(d) ∃c ∈ ℝ, ∃n ∈ ℕ, uₙ ≤ c</p><p>(f) ∃n ∈ ℕ, ∀c ∈ ℝ, uₙ ≤ c</p><p><b>Justifie chaque réponse.</b> Les assertions (a), (b) et (e) du même exercice viennent d'être vues dans cette leçon.</p><p>Indice, qui n'est pas dans le TD : la réponse peut être « toutes les suites », « aucune suite », ou une famille de suites (comme « les suites majorées »).</p>`,`<span class="who">Corrigé officiel (Moodle), recopié</span><p><b>(c) Aucune suite.</b> Pour le voir, il suffit de prendre c = u₀ − 1 et n = 0 : l'inégalité u₀ ≤ u₀ − 1 est fausse. Or un seul cas faux suffit à rendre faux un « ∀c, ∀n ».</p><p><b>(d) Toutes les suites.</b> En effet, si on choisit c = u₀ et n = 0, on obtient u₀ ≤ u₀, qui est vraie. Un seul cas vrai suffit pour un « ∃c, ∃n ».</p><p><b>(f) Aucune suite.</b> Sa négation est : ∀n ∈ ℕ, ∃c ∈ ℝ, uₙ &gt; c. Elle est vraie pour toute suite : pour chaque entier n, on peut choisir c = uₙ − 1. Donc (f) est fausse pour toute suite.</p><p>Remarque du corrigé : quand le sens d'une assertion t'échappe, écris sa négation. C'est souvent elle qui est facile à comprendre.</p>`,["(c) : un c et un n précis qui rendent l'inégalité fausse","(d) : un c et un n précis qui la rendent vraie","(f) : la négation écrite, puis prouvée avec c = uₙ − 1","Chaque réponse est justifiée, pas seulement affirmée"],6),
 K("Comment prouve-t-on une phrase qui commence par ∀ ? Par ∃ ? Et comment les réfute-t-on ?","∀ : « Soit x quelconque », puis la preuve ; pour réfuter, un contre-exemple suffit. ∃ : un exemple suffit ; pour réfuter, il faut montrer que ça échoue pour tous les x."),
 K("Comment écrit-on la négation d'une phrase avec des quantificateurs ? Que deviennent « P ⇒ Q » et « a &lt; b » ?","On échange ∀ et ∃, puis on nie la fin. non(P ⇒ Q) = P et non Q. non(a &lt; b) = a ≥ b.")]},

/* ------------------------------------------------------------------ */
{id:"a-abs",t:"Valeur absolue et distance",min:14,goal:"Manipuler |x − a| ≤ d et l'inégalité triangulaire, résoudre des (in)équations (TD 1, ex. 3 et 6).",steps:[
 Q("Que vaut |−7| ?",["7","−7","0","49"],0,"La valeur absolue enlève le signe : |x| = x si x ≥ 0, et |x| = −x si x &lt; 0. Ici −7 &lt; 0, donc |−7| = −(−7) = 7. C'est aussi la distance entre −7 et 0."),
 L("|x| et la distance",`<p>|x| vaut x si x ≥ 0 et −x si x &lt; 0. C'est la <b>distance entre x et 0</b>, et <b>|b − a| est la distance entre a et b</b>.</p>${box("|x − a| ≤ d  ⇔  a − d ≤ x ≤ a + d        |x − a| &lt; d  ⇔  a − d &lt; x &lt; a + d")}<p>Les signes : ⇔ se lit « si et seulement si » (les deux côtés disent la même chose) ; d est un nombre positif ou nul ; {x | …} se lit « l'ensemble des x tels que … » ; [a − d, a + d] désigne tous les réels de a − d à a + d, bornes comprises, et ]a − d, a + d[ les mêmes sans les deux bornes (la leçon suivante revient sur ces crochets).</p><p>Autrement dit, {x | |x − a| ≤ d} = [a − d, a + d] : l'intervalle de centre a et de rayon d. C'est la phrase qu'on utilise sans cesse avec ε.</p>`),
 Q("Que vaut {x ∈ ℝ | |x + 1| ≤ 4} ?",["[−5, 3]","[−3, 5]","]−5, 3[","[3, 5]"],0,"|x + 1| = |x − (−1)| : c'est la distance entre x et −1. Elle vaut au plus 4 quand −1 − 4 ≤ x ≤ −1 + 4, c'est-à-dire −5 ≤ x ≤ 3. Le centre est −1, et pas 1 : avec le centre 1, on trouverait [−3, 5]. L'inégalité est large (≤), donc les bornes −5 et 3 sont comprises : crochets fermés."),
 L("Inégalités triangulaires",`${box("||a| − |b|| ≤ |a + b| ≤ |a| + |b|        ||a| − |b|| ≤ |a − b|")}<p>Elles servent à <b>majorer</b> une valeur absolue compliquée, c'est-à-dire à la remplacer par quelque chose de plus grand mais de plus simple. Exemple : pour tout réel x, |x + sin(x)| ≤ |x| + |sin(x)| ≤ |x| + 1, car |sin(x)| ≤ 1.</p><p>À connaître aussi : <b>|a × b| = |a| × |b|</b>. Exemple : pour n ∈ ℕ, |n sin(n)| = n × |sin(n)| ≤ n.</p><p>Attention : |a − b| ≤ |a| − |b| est <b>fausse</b> en général (a = 0, b = 1 : 1 ≤ −1 est faux).</p>`),
 Q("Quelle inégalité est vraie pour tous réels a, b ?",["|a + b| ≤ |a| + |b|","|a − b| ≤ |a| − |b|","|a + b| = |a| + |b|","|a − b| ≥ |a| + |b|"],0,"C'est l'inégalité triangulaire. Les trois autres sont fausses pour certains a et b : « |a − b| ≤ |a| − |b| » avec a = 0 et b = 1 donne 1 ≤ −1 (TD 1, ex. 3 a) ; « |a + b| = |a| + |b| » avec a = 1 et b = −1 donne 0 = 2 ; « |a − b| ≥ |a| + |b| » avec a = b = 1 donne 0 ≥ 2."),
 S("Résoudre avec des valeurs absolues (TD 1, ex. 6)","Résoudre dans ℝ les équations et inéquations suivantes : (a) |x − 3| = 5 ; (b) |x + 3| ≤ 5 ; (c) |x + 2| &gt; 7 ; (d) |2x − 4| ≤ |x + 2|. Le (d) prend trois étapes.",[
  {w:"|x − 3| = 5 ⇔ x − 3 = 5 ou x − 3 = −5 ⇔ x = 8 ou x = −2.",why:"Distance 5 à 3 : deux points, de part et d'autre."},
  {w:"|x + 3| ≤ 5 ⇔ −5 ≤ x + 3 ≤ 5 ⇔ −8 ≤ x ≤ 2 : S = [−8, 2].",why:"Distance au plus 5 de −3."},
  {w:"|x + 2| &gt; 7 ⇔ x + 2 &gt; 7 ou x + 2 &lt; −7 ⇔ x &gt; 5 ou x &lt; −9 : S = ]−∞, −9[ ∪ ]5, +∞[.",why:"Plus loin que 7 de −2 : deux morceaux."},
  {w:"|2x − 4| ≤ |x + 2| ⇔ (2x − 4)² ≤ (x + 2)².",why:"Deux nombres positifs ou nuls sont rangés dans le même ordre que leurs carrés, et |a|² = a²."},
  {w:"On développe : 4x² − 16x + 16 ≤ x² + 4x + 4, c'est-à-dire 3x² − 20x + 12 ≤ 0.",why:"On passe tout à gauche : 4x² − x² = 3x², −16x − 4x = −20x, 16 − 4 = 12."},
  {w:"Δ = 20² − 4 × 3 × 12 = 256 = 16². Les racines sont (20 − 16)/6 = 2/3 et (20 + 16)/6 = 6. Donc S = [2/3, 6].",why:"Un trinôme dont le coefficient de x² est positif (ici 3) est négatif ou nul entre ses racines."}]),
 Q("Que vaut {x | |x − 1| &lt; 2} ?",["]−1, 3[","[−1, 3]","]1, 3[","]−3, 1["],0,"Centre 1, rayon 2, inégalité stricte : intervalle ouvert ]−1, 3[ (CC1 2024-2025, tableau)."),
 P("TD 1, exercice 10, sur papier",`<p>Le plus grand élément de l'ensemble {x, y} est noté max(x, y) (et de même on note min(x, y) le plus petit…) ; démontrer que, pour tous x et y réels,</p>${box("max(x, y) = (x + y + |x − y|)/2        min(x, y) = (x + y − |x − y|)/2")}<p>Indice, qui n'est pas dans le TD : commence par le cas x ≤ y. Que vaut alors |x − y| ?</p>`,`<span class="who">Corrigé officiel (manuscrit, Moodle), recopié</span><p>Soient x et y deux réels. Supposons x ≤ y. Alors x − y ≤ 0, donc |x − y| = y − x, et :</p><ul><li>max(x, y) = y = (x + y)/2 + (y − x)/2 = (x + y + |x − y|)/2 ;</li><li>min(x, y) = x = (x + y)/2 − (y − x)/2 = (x + y − |x − y|)/2.</li></ul><p>Par symétrie des rôles de x et y, c'est toujours vrai quand y ≤ x.</p><p>Remarque du corrigé : si tu n'es pas à l'aise avec l'argument de symétrie, rédige aussi le cas y ≤ x (alors |x − y| = x − y, max(x, y) = x et min(x, y) = y, et le même calcul marche).</p><p>L'idée, sur la droite réelle : (x + y)/2 est le milieu du segment, et |x − y|/2 la moitié de sa longueur.</p>`,["« Soient x et y deux réels » écrit d'abord","Un cas choisi (x ≤ y), et |x − y| remplacé par y − x","Les deux formules vérifiées par le calcul","L'autre cas traité, ou la phrase « par symétrie des rôles de x et y »"],8),
 K("Que veut dire |x − a| ≤ d ? Écris-le sans valeur absolue.","a − d ≤ x ≤ a + d : x est à distance au plus d de a. Avec &lt; : intervalle ouvert."),
 K("Quelles sont les inégalités triangulaires pour |a + b| et |a − b| ?","||a| − |b|| ≤ |a + b| ≤ |a| + |b|, et ||a| − |b|| ≤ |a − b|. Mais |a − b| ≤ |a| − |b| est fausse.")]},

/* ------------------------------------------------------------------ */
{id:"a-intervalles",t:"Intervalles et partie entière",min:12,goal:"Reconnaître un intervalle (1ʳᵉ colonne du tableau du CC) et utiliser la partie entière.",steps:[
 Q("[0, 3] ∪ ]2, 4[ est-il un intervalle ?",["Oui, c'est [0, 4[","Non, c'est une réunion","Oui, c'est [0, 4]"],0,"Les deux morceaux se chevauchent (les nombres entre 2 et 3 sont dans les deux) : mis ensemble, ils couvrent tout de 0 à 4, sans trou. 0 est gardé (crochet fermé de [0, 3]), mais pas 4 (crochet ouvert de ]2, 4[) : la réunion est [0, 4[, et pas [0, 4]. C'est la première ligne du tableau du CC1 2024-2025."),
 L("Ce qu'est un intervalle",`<p>Un intervalle est un « morceau d'un seul tenant » de ℝ : [a, b], [a, b[, ]a, b], ]a, b[, [a, +∞[, ]a, +∞[, ]−∞, b], ]−∞, b[, ℝ ou ∅.</p><p>Les notations : un crochet tourné vers l'intérieur garde la borne, un crochet tourné vers l'extérieur l'enlève ([0, 1[ contient 0 mais pas 1). A ∪ B : les réels qui sont dans A <b>ou</b> dans B. A ∩ B : ceux qui sont dans les deux. A ∖ B : ceux de A qui ne sont pas dans B.</p><p><b>Critère</b> (convexité) : A est un intervalle si et seulement si <b>∀α, β ∈ A, [α, β] ⊂ A</b> : entre deux points de A, tout est dans A.</p><p>Donc, pour montrer que A <b>n'est pas</b> un intervalle : deux points de A et un point entre eux qui n'est pas dans A. ℝ ∖ {1, 2} : 0 et 3 y sont, mais pas 1.</p><p>Rappel : ℚ est l'ensemble des nombres <b>rationnels</b>, ceux qui s'écrivent comme une fraction de deux entiers (3/4, −5, 0,2). √2 n'est pas rationnel.</p>`),
 Q("ℚ est-il un intervalle ?",["Non : 1 et 2 sont dans ℚ, mais pas √2, qui est entre eux","Oui : entre deux rationnels, il y a toujours un autre rationnel","Oui : ℚ n'est pas borné, c'est donc ]−∞, +∞["],0,"Un intervalle contient tous les nombres compris entre deux de ses éléments. 1 et 2 sont dans ℚ, mais √2, qui est entre 1 et 2, n'est pas rationnel. Donc ℚ ne contient pas [1, 2] en entier : ce n'est pas un intervalle (TD 1, ex. 7a). Entre deux rationnels il y a bien un autre rationnel, mais aussi des irrationnels : ce sont eux qui manquent. Et ]−∞, +∞[, c'est ℝ, pas ℚ."),
 Q("{x ∈ ℝ | x² − 1 &gt; 0} est-il un intervalle ?",["Non : c'est ]−∞, −1[ ∪ ]1, +∞[, en deux morceaux","Oui : c'est ]1, +∞[, car x² &gt; 1 donne x &gt; 1","Oui : c'est ]−1, 1[, entre les deux racines"],0,"−2 et 2 sont dedans, mais pas 0 qui est entre eux (TD 1, ex. 7g). x² &gt; 1 donne aussi x &lt; −1 (par exemple x = −2). Et x² − 1 est positif à l'extérieur des racines, pas entre."),
 L("Partie entière",`<p>Pour tout réel x, il existe un <b>unique entier</b> n tel que <b>n ≤ x &lt; n + 1</b>. On le note E(x) : c'est l'entier juste en dessous (ou égal).</p><p>E(2,7) = 2 ; E(−2,7) = −3 (attention !) ; E(5) = 5. On a toujours <b>x − 1 &lt; E(x) ≤ x</b>.</p><p>Elle sert à <b>choisir un rang</b> dans les preuves avec ε : N = E(1/ε) + 1 est un entier qui vérifie N &gt; 1/ε.</p>`),
 Q("Que vaut E(−3,2), la partie entière de −3,2 ?",["−4","−3","3","−3,2"],0,"E(x) est le plus grand entier inférieur ou égal à x. Les entiers autour de −3,2 sont −4 et −3 : −4 ≤ −3,2 &lt; −3. Le plus grand entier sous −3,2 est −4, donc E(−3,2) = −4. Le piège : ce n'est pas −3, qui est plus grand que −3,2."),
 Q("Pourquoi N = E(1/ε) + 1 vérifie-t-il N &gt; 1/ε ?",["Parce que 1/ε &lt; E(1/ε) + 1, par définition de la partie entière","Parce que E(1/ε) = 1/ε, et on ajoute encore 1","Parce que ε &gt; 1, donc 1/ε est plus petit que 1","Parce que la partie entière arrondit au-dessus : E(1/ε) &gt; 1/ε"],0,"x &lt; E(x) + 1 pour tout x : avec x = 1/ε, on obtient 1/ε &lt; N. E(1/ε) ne vaut 1/ε que si 1/ε est entier, ε n'a aucune raison d'être plus grand que 1, et la partie entière arrondit en dessous : E(x) ≤ x."),
 P("TD 1, exercice 7 : (b), (c), (e), (f) et (h), sur papier",`<p>Parmi les sous-ensembles de ℝ suivants, lesquels sont des intervalles ?</p><p>(b) [1, 2] ∪ [2, 3[</p><p>(c) ℝ*₊</p><p>(e) {(t² + 1)/2 | t ∈ ℝ}</p><p>(f) les solutions de l'équation |x + 3| ≤ 7</p><p>(h) le complémentaire d'un intervalle de ℝ</p><p>Les ensembles (a), (d) et (g) du même exercice viennent d'être vus dans cette leçon.</p><p>Deux rappels, qui ne sont pas dans le TD : ℝ*₊ est l'ensemble des réels strictement positifs ; le complémentaire de A est l'ensemble des réels qui ne sont pas dans A.</p>`,`<span class="who">Corrigé écrit par moi (pas de corrigé officiel)</span><p><b>(b) Oui</b> : les deux morceaux se touchent en 2, et [1, 2] ∪ [2, 3[ = [1, 3[.</p><p><b>(c) Oui</b> : ℝ*₊ = ]0, +∞[.</p><p><b>(e) Oui.</b> Quand t parcourt ℝ, t² prend toutes les valeurs de [0, +∞[, donc (t² + 1)/2 prend toutes les valeurs de [1/2, +∞[ : c'est l'intervalle [1/2, +∞[.</p><p><b>(f) Oui.</b> |x + 3| ≤ 7 ⇔ −7 ≤ x + 3 ≤ 7 ⇔ −10 ≤ x ≤ 4 : c'est [−10, 4].</p><p><b>(h) Pas toujours.</b> Le complémentaire de [0, 1] est ]−∞, 0[ ∪ ]1, +∞[ : ce n'est pas un intervalle (−1 et 2 y sont, mais pas 1/2). Mais le complémentaire de ]−∞, 0] est ]0, +∞[, qui est un intervalle.</p>`,["(b), (c), (e) : l'intervalle est écrit, avec les bons crochets","(f) : l'encadrement −7 ≤ x + 3 ≤ 7 est écrit","(h) : un exemple où ce n'est pas un intervalle, et un exemple où c'en est un","Pour dire « non » : deux points de l'ensemble et un point entre eux qui n'y est pas"],6),
 K("Quelle propriété caractérise un intervalle A de ℝ ? Comment montrer qu'un ensemble n'est pas un intervalle ?","∀α, β ∈ A, [α, β] ⊂ A. Pour dire non : deux points de A et un point entre eux hors de A."),
 K("Quelle est la définition de la partie entière E(x) d'un réel x ? À quoi sert l'entier N = E(1/ε) + 1 ?","E(x) est l'unique entier n tel que n ≤ x &lt; n + 1 ; donc x − 1 &lt; E(x) ≤ x. N = E(1/ε) + 1 est un entier strictement plus grand que 1/ε : c'est le rang qu'on choisit dans les preuves de limite.")]},

/* ------------------------------------------------------------------ */
{id:"a-bornes",t:"Majorant, maximum, borne supérieure",min:16,goal:"Remplir sans erreur le tableau inf / min / max / sup du CC (4 points en 2024 et en 2025).",steps:[
 Q("[0, 1[ a-t-il un plus grand élément ?",["Non : 1 n'est pas dans [0, 1[, et tout x &lt; 1 est dépassé","Oui : 1, la borne de droite de l'intervalle","Oui : 0,999…, le dernier nombre avant 1","Oui : 0, car le crochet [ est fermé de ce côté"],0,"Pour tout x de [0, 1[, (x + 1)/2 est encore dans [0, 1[ et plus grand que x. 0,999… (avec une infinité de 9) est égal à 1, donc pas dans [0, 1[. Et 0 est le plus petit élément, pas le plus grand.",{diag:false}),
 L("Majorant et plus grand élément",`<ul><li>m est un <b>majorant</b> de A si ∀a ∈ A, a ≤ m. A est <b>majorée</b> si elle a un majorant. Un majorant n'est <b>pas forcément dans A</b>.</li><li>A a un <b>plus grand élément</b> (max) x si x ∈ A et ∀a ∈ A, a ≤ x : c'est un majorant <b>qui est dans A</b>.</li></ul><p>Pareil en bas : minorant, minorée, plus petit élément (min). Bornée = majorée et minorée.</p><p>Exemple : 5, 1 et 1,2 sont des majorants de [0, 1[ ; il n'a pas de max.</p>`),
 Q("On note A = [−1, 0[. Laquelle de ces phrases est vraie ?",["−1 = min(A) et A n'a pas de max","0 = max(A), car 0 est la borne de droite","A n'a pas de min, car l'intervalle est ouvert","A n'est pas majorée, car elle n'a pas de max"],0,"−1 ∈ A et minore A : c'est le min. 0 majore A mais n'est pas dans A (TD 1, ex. 8). A n'est ouvert que du côté de 0, et A est majorée (par 0) même sans maximum."),
 L("La borne supérieure",`<p>Si A est <b>non vide et majorée</b>, l'ensemble de ses majorants a un plus petit élément : c'est la <b>borne supérieure</b>, sup(A), le <b>plus petit des majorants</b>. Dans ℝ, elle existe toujours dans ce cas.</p><ul><li>Si A a un max, alors sup(A) = max(A).</li><li>Si A n'est pas majorée, elle n'a pas de sup (dans ℝ).</li></ul><p>De même, inf(A) est le plus grand des minorants.</p>${box("[0, 1[ : sup = 1 (pas de max), inf = min = 0.    {1/n | n ∈ ℕ*} : sup = max = 1, inf = 0 (pas de min).")}<p>(ℕ* désigne les entiers naturels sans 0 : 1, 2, 3… L'ensemble {1/n | n ∈ ℕ*} contient donc 1, 1/2, 1/3, …)</p>`),
 Q("Que dire de l'ensemble ℕ des entiers naturels (0, 1, 2, …) ?",["inf = min = 0 ; ni max ni sup","inf = min = 0 ; pas de max, et sup = +∞","pas de min, mais inf = 0 ; ni max ni sup","inf = min = 1 ; ni max ni sup"],0,"0 est dans ℕ et il est en dessous de tous les autres entiers naturels : c'est le min, donc aussi l'inf. ℕ n'est pas majoré (aucun réel n'est au-dessus de tous les entiers) : pas de max, et pas de sup non plus. Un sup est un réel, et +∞ n'en est pas un : dans le tableau du CC, on répond « non ». Enfin ℕ commence à 0, pas à 1 (TD 1, ex. 8)."),
 S("Le tableau du CC1 2024-2025",`<p>Complète chaque ligne : intervalle ? inf, min, max, sup (« non » s'ils n'existent pas).</p><div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Sous-ensemble</th><th>Intervalle ?</th><th>Inf ?</th><th>Min ?</th><th>Max ?</th><th>Sup ?</th></tr></thead><tbody><tr><td>[0, 3] ∪ ]2, 4[</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>ℝ ∖ [1, 2[</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>ℚ ∩ [√2, 2[</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>{x | |x − 1| &lt; 2}</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table></div>`,[
  {w:"[0, 3] ∪ ]2, 4[ = [0, 4[ : intervalle ; inf = min = 0 ; pas de max ; sup = 4.",why:"4 majore tout et on s'en approche, mais 4 n'est pas dedans."},
  {w:"ℝ ∖ [1, 2[ = ]−∞, 1[ ∪ [2, +∞[ : pas un intervalle ; ni inf, ni min, ni max, ni sup.",why:"Il y a un trou (0 et 2 y sont, mais pas 1), et l'ensemble n'est ni minoré ni majoré."},
  {w:"ℚ ∩ [√2, 2[ : pas un intervalle ; inf = √2, pas de min ; pas de max, sup = 2.",why:"√2 et 2 sont les bornes, mais aucune n'est dans l'ensemble : √2 n'est pas rationnel, et 2 est exclu."},
  {w:"{x | |x − 1| &lt; 2} = ]−1, 3[ : intervalle ; inf = −1 et sup = 3, pas de min ni de max.",why:"Intervalle ouvert : bornes non atteintes."}]),
 Q("F = {1/n − 1/p | n, p ∈ ℕ*} (n et p sont des entiers à partir de 1). Quelle est sa borne supérieure ?",["sup F = 1, et F n'a pas de max","sup F = 1, et c'est aussi le max de F","sup F = 0, atteint quand n = p","sup F = 1/2, atteint pour n = 1 et p = 2"],0,"1/n ≤ 1 et 1/p &gt; 0, donc 1/n − 1/p &lt; 1 : 1 majore F, sans être atteint, donc ce n'est pas un max. Avec n = 1, on obtient 1 − 1/p, qui s'approche de 1 autant qu'on veut quand p grandit : aucun nombre plus petit que 1 ne majore F, donc sup F = 1. 0 et 1/2 sont bien dans F, mais 1 − 1/3 = 2/3 les dépasse (TD 1, ex. 8)."),
 P("CC1 2025-2026, partie 2, question 3 : le tableau, sur papier",`<p>Complétez le tableau pour chaque sous-ensemble de ℝ. On ne demande pas de justification.</p><p>Dans la 1ʳᵉ colonne : répondez non si le sous-ensemble n'est pas un intervalle, donner cet intervalle si le sous-ensemble est un intervalle. Dans les colonnes suivantes : répondez non si le sous-ensemble n'a pas de borne inférieure, de plus petit élément, de plus grand élément ou de borne supérieure et donnez leur valeur lorsqu'elle existe.</p><div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Sous-ensemble</th><th>Intervalle ?</th><th>Inf ?</th><th>Min ?</th><th>Max ?</th><th>Sup ?</th></tr></thead><tbody><tr><td>{1/(1 + t), t ∈ ℝ⁺}</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>{x ∈ ℝ, x &gt; 2}</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>{x ∈ ℚ, x² ≤ 2}</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table></div><p>(Rappel du sujet : dans cette partie, les réponses incorrectes peuvent donner des points négatifs.)</p>`,`<span class="who">Tableau du corrigé officiel, recopié ; les explications sont de moi</span><div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Sous-ensemble</th><th>Intervalle ?</th><th>Inf ?</th><th>Min ?</th><th>Max ?</th><th>Sup ?</th></tr></thead><tbody><tr><td>{1/(1 + t), t ∈ ℝ⁺}</td><td>]0, 1]</td><td>0</td><td>Non</td><td>1</td><td>1</td></tr><tr><td>{x ∈ ℝ, x &gt; 2}</td><td>]2, +∞[</td><td>2</td><td>Non</td><td>Non</td><td>Non</td></tr><tr><td>{x ∈ ℚ, x² ≤ 2}</td><td>Non</td><td>−√2</td><td>Non</td><td>Non</td><td>√2</td></tr></tbody></table></div><p>Le corrigé précise : {x ∈ ℚ, x² ≤ 2} = [−√2, √2] ∩ ℚ.</p><ul><li>Quand t parcourt ℝ⁺ = [0, +∞[, 1 + t parcourt [1, +∞[, donc 1/(1 + t) parcourt ]0, 1]. La valeur 1 est atteinte (t = 0) : c'est le max et le sup. 0 n'est jamais atteint : inf = 0, pas de min.</li><li>]2, +∞[ : 2 n'est pas dans l'ensemble (inf = 2, pas de min) ; l'ensemble n'est pas majoré (ni max, ni sup).</li><li>[−√2, √2] ∩ ℚ n'est pas un intervalle : entre deux rationnels, il y a toujours un irrationnel. Ses bornes −√2 et √2 ne sont pas rationnelles, donc pas dans l'ensemble : ni min, ni max.</li></ul>`,["Chaque ensemble est réécrit sous forme simple avant de remplir la ligne","Une borne qui n'est pas dans l'ensemble : « Non » pour le min ou le max","Un ensemble non majoré : « Non » pour le max et pour le sup","Au CC, une case fausse peut enlever des points : une case dont tu n'es pas sûr se laisse vide"],8),
 K("Pour une partie A de ℝ, quelle est la différence entre un majorant, le maximum et la borne supérieure ?","Majorant : ≥ tous les éléments, pas forcément dans A. Max : un majorant dans A. Sup : le plus petit des majorants (existe si A non vide majorée) ; si le max existe, sup = max."),
 K("Pour A = [0, 1[, donne la borne inférieure, le minimum, le maximum et la borne supérieure, quand ils existent.","inf = min = 0 ; pas de max ; sup = 1.")]},

/* ------------------------------------------------------------------ */
{id:"a-carac-sup",t:"Borne sup avec ε, point adhérent",min:17,goal:"Réciter la caractérisation de la borne sup et prouver « 1 = sup ]0, 1[ » : la question de cours du CC (2 points).",steps:[
 Q("Pour montrer que 1 est le plus petit majorant de ]0, 1[, que faut-il montrer en plus de « 1 est un majorant » ?",["Qu'aucun nombre plus petit que 1 n'est un majorant","Que 1 est dans ]0, 1[, pour que ce soit le plus petit","Que 0 est un minorant, de l'autre côté de l'intervalle"],0,"Le plus petit des majorants : tout nombre en dessous doit être dépassé par un élément de l'ensemble. Un sup n'a pas besoin d'être dans l'ensemble (ici 1 ∉ ]0, 1[), et le minorant ne joue aucun rôle."),
 L("Caractérisation avec ε",`<p>Soit A non vide et majorée, et m ∈ ℝ. Il y a équivalence entre :</p>${box("m = sup(A)   ⇔   m est un majorant de A  et  ∀ε &gt; 0, ∃a ∈ A, m − ε &lt; a")}<p>« Si on descend un tout petit peu sous m (de ε), on trouve encore un élément de A » : aucun nombre plus petit que m ne majore A.</p><p>Au CC 2025, la question « Donner une caractérisation de la borne supérieure » attendait <b>exactement</b> cette phrase (et pas la définition « plus petit des majorants »).</p>`),
 Q("Quelle phrase est la caractérisation de m = sup(A) ?",["m majore A et ∀ε &gt; 0, ∃a ∈ A, m − ε &lt; a","m majore A et m ∈ A","∀ε &gt; 0, ∃a ∈ A, m + ε &lt; a","m est le plus grand élément de A"],0,"Deux morceaux : m est un majorant, et dès qu'on descend de ε sous m, on trouve un élément de A au-dessus de m − ε. « m majore A et m ∈ A » est la définition du maximum, qui n'existe pas toujours (sup [0, 1[ = 1 n'est pas dans [0, 1[). « m + ε &lt; a » voudrait dire qu'un élément de A dépasse m : impossible si m majore A."),
 L("Point adhérent",`<p>x est <b>adhérent</b> à A si on peut trouver des points de A aussi près de x qu'on veut :</p>${box("∀ε &gt; 0, ∃a ∈ A, |x − a| &lt; ε")}<p><b>Théorème</b> : x est adhérent à A ⇔ il existe une suite (aₙ) d'éléments de A qui converge vers x.</p><p>Et une autre caractérisation : <b>m = sup(A) ⇔ m majore A et il existe une suite d'éléments de A qui converge vers m</b>.</p><p>Exemples : 1 est adhérent à [0, 1[ ; 0 est adhérent à ℝ* ; tout réel est adhérent à ℚ.</p>`),
 Q("Pourquoi 1 est-il adhérent à [0, 1[ ?",["Parce que la suite uₙ = 1 − 1/n (n ≥ 1) est dans [0, 1[ et tend vers 1","Parce que 1 ∈ [0, 1[ : le crochet le contient","Parce que 1 majore [0, 1[ : tout majorant est adhérent"],0,"C'est la réponse officielle du CC1 2024-2025 : une suite d'éléments de A qui converge vers 1. 1 n'est pas dans [0, 1[ (le crochet est ouvert de son côté), et un majorant comme 5 n'est pas adhérent."),
 S("Question de cours du CC1 2025-2026 : 1 = sup ]0, 1[","L'énoncé : « b) Montrer que 1 est la borne supérieure de ]0 ; 1[. » Le a) demandait une caractérisation de la borne supérieure (2 points pour les deux).",[
  {w:"Pour tout x ∈ ]0, 1[, x &lt; 1 : donc 1 est un majorant de ]0, 1[.",why:"Première moitié de la caractérisation."},
  {w:"Pour n ≥ 2, uₙ = 1 − 1/n est dans ]0, 1[ (car 0 &lt; 1/n &lt; 1), et uₙ → 1.",why:"On prend n ≥ 2 : pour n = 1, u₁ = 0 n'est pas dans ]0, 1[."},
  {w:"1 majore ]0, 1[ et est limite d'une suite d'éléments de ]0, 1[ : donc 1 = sup ]0, 1[.",why:"On cite la caractérisation par les suites."},
  {w:"Variante avec ε : soit ε ∈ ]0, 1[ ; a = 1 − ε/2 est dans ]0, 1[ et 1 − ε &lt; a. (Si ε ≥ 1, a = 1/2 convient.)",why:"La caractérisation avec ε marche aussi : on exhibe a."}]),
 Q("Avec la caractérisation, pour montrer m = sup(A), que fait-on après « m est un majorant » ?",["« Soit ε &gt; 0 », puis on trouve un a ∈ A avec m − ε &lt; a","On montre que m ∈ A : un sup est toujours dans A","On calcule le max de A, qui est égal au sup","On prend ε = 1 et on trouve un a ∈ A avec m − 1 &lt; a"],0,"Un ∀ε : on fixe ε quelconque, puis on exhibe un élément de A (ou on utilise une suite qui converge vers m). Le sup n'est pas forcément dans A, A n'a pas toujours de max, et un seul ε (comme ε = 1) ne suffit pas : il faut tous les ε &gt; 0."),
 P("TD 2, exercice 18 (d'après le CC2 2022), sur papier",`<p>On considère l'ensemble S = {(n − 1/n)/(n + 1/n) | n ∈ ℕ*}.</p><p>S admet-il une borne supérieure ? une borne inférieure ? un minimum ? un maximum ? Et si oui, les déterminer.</p><p><b>Justifier soigneusement et de façon complète.</b></p><p>Indice, qui n'est pas dans le TD : commence par multiplier en haut et en bas par n.</p>`,`<span class="who">Corrigé écrit par moi (pas de corrigé officiel)</span><p>Pour n ∈ ℕ*, notons sₙ = (n − 1/n)/(n + 1/n). En multipliant en haut et en bas par n : <b>sₙ = (n² − 1)/(n² + 1) = 1 − 2/(n² + 1)</b>.</p><p><b>Minimum et borne inférieure.</b> Pour tout n ≥ 1, n² − 1 ≥ 0, donc sₙ ≥ 0 : 0 est un minorant de S. De plus s₁ = 0, donc 0 ∈ S. Un minorant qui appartient à l'ensemble est son plus petit élément : <b>min S = 0</b>, et donc <b>inf S = 0</b>.</p><p><b>Borne supérieure.</b> S est non vide, et pour tout n ≥ 1, sₙ = 1 − 2/(n² + 1) &lt; 1 : S est majoré par 1, donc S admet une borne supérieure. Montrons que c'est 1 avec la caractérisation. 1 est un majorant de S. Soit ε &gt; 0. Choisissons un entier n ≥ 1 tel que n &gt; 2/ε. Alors n² + 1 &gt; n &gt; 2/ε, donc 2/(n² + 1) &lt; ε, donc sₙ &gt; 1 − ε : il existe un élément de S strictement supérieur à 1 − ε. Ainsi <b>sup S = 1</b>.</p><p><b>Pas de maximum.</b> Un maximum serait égal à sup S = 1. Or sₙ &lt; 1 pour tout n : 1 ∉ S. Donc <b>S n'a pas de maximum</b>.</p><p>Écrire seulement « sup = 1, inf = min = 0, pas de max » ne rapporte pas les points : l'énoncé demande de tout justifier.</p>`,["Chaque réponse est justifiée : c'est ce que l'énoncé impose","L'expression simplifiée : (n² − 1)/(n² + 1) = 1 − 2/(n² + 1)","min S = 0 : 0 minore S, et 0 ∈ S (pour n = 1)","sup S = 1 : 1 majore S, puis « Soit ε &gt; 0 » et un n explicite","Pas de maximum : 1 n'est pas dans S"],12),
 K("Comment caractérise-t-on m = sup(A) avec ε ? Et avec une suite ?","m est un majorant de A et ∀ε &gt; 0, ∃a ∈ A, m − ε &lt; a. Ou : m majore A et une suite d'éléments de A converge vers m."),
 K("Que veut dire « x est adhérent à A », pour une partie A de ℝ ?","∀ε &gt; 0, ∃a ∈ A, |x − a| &lt; ε ; équivaut à : une suite d'éléments de A converge vers x. 1 est adhérent à [0, 1[ (uₙ = 1 − 1/n).")]},

/* ------------------------------------------------------------------ */
{id:"a-suites",t:"Suites : le vocabulaire",min:11,goal:"Écrire avec des quantificateurs « croissante », « majorée », « à partir d'un certain rang » (TD 2, ex. 1 à 3).",steps:[
 Q("Comment montre-t-on qu'une suite (uₙ) est croissante ?",["On montre uₙ₊₁ − uₙ ≥ 0 pour tout n","On calcule u₀ et u₁","On montre qu'elle tend vers +∞"],0,"Par définition, (uₙ) est croissante si chaque terme est plus grand ou égal au précédent : pour tout n, uₙ₊₁ ≥ uₙ. En pratique, on étudie le signe de uₙ₊₁ − uₙ : s'il est toujours positif ou nul, la suite est croissante."),
 L("Les définitions",`<ul><li><b>Croissante</b> : ∀n ∈ ℕ, uₙ₊₁ ≥ uₙ. <b>Décroissante</b> : uₙ₊₁ ≤ uₙ. Monotone : l'un ou l'autre.</li><li><b>Majorée</b> : ∃M ∈ ℝ, ∀n ∈ ℕ, uₙ ≤ M. <b>Minorée</b> : ∃m, ∀n, uₙ ≥ m. <b>Bornée</b> : ∃C, ∀n, |uₙ| ≤ C.</li><li><b>Périodique</b> : ∃T ∈ ℕ*, ∀n ∈ ℕ, u<sub>n+T</sub> = uₙ. Les termes se répètent tous les T rangs (T = 0 est interdit).</li><li><b>À partir d'un certain rang</b> : on ajoute « ∃N₀ ∈ ℕ, ∀n ≥ N₀ » devant. Exemple : croissante à partir d'un certain rang : ∃N₀ ∈ ℕ, ∀n ≥ N₀, uₙ₊₁ ≥ uₙ.</li></ul><p>Ne pas confondre la suite (uₙ) et l'ensemble de ses valeurs {uₙ | n ∈ ℕ}.</p>`),
 Q("Comment s'écrit « la suite (uₙ) est majorée » avec des quantificateurs ?",["∃M ∈ ℝ, ∀n ∈ ℕ, uₙ ≤ M","∀n ∈ ℕ, ∃M ∈ ℝ, uₙ ≤ M","∀M ∈ ℝ, ∃n ∈ ℕ, uₙ ≤ M"],0,"Un même M pour tous les n : le ∃M vient avant le ∀n. La phrase qui commence par « ∀n ∈ ℕ, ∃M » est vraie pour toutes les suites (on prend M = uₙ)."),
 L("Méthodes pour la monotonie",`<ul><li><b>Différence</b> : étudier le signe de uₙ₊₁ − uₙ.</li><li><b>Quotient</b> (si tous les termes sont &gt; 0) : comparer uₙ₊₁/uₙ à 1.</li><li><b>Récurrence</b> : pour une suite définie par uₙ₊₁ = f(uₙ).</li></ul><p>Exemple : uₙ = 1 + 1/n pour n ≥ 1. uₙ₊₁ − uₙ = 1/(n + 1) − 1/n = −1/(n(n + 1)) &lt; 0, donc (uₙ) est décroissante.</p>`),
 Q("Une suite (uₙ) a tous ses termes &gt; 0 et vérifie uₙ₊₁/uₙ &lt; 1 pour tout n. Quel est son sens de variation ?",["Strictement décroissante, car uₙ₊₁ &lt; uₙ","Croissante, car tous les termes sont positifs","Constante, car le quotient reste plus petit que 1","Décroissante seulement si u₀ &lt; 1"],0,"On part de uₙ₊₁/uₙ &lt; 1. On multiplie les deux côtés par uₙ, qui est strictement positif, donc le sens de l'inégalité ne change pas : uₙ₊₁ &lt; uₙ. Chaque terme est plus petit que le précédent : la suite est strictement décroissante. Être positive ne dit rien du sens de variation, et la valeur de u₀ ne compte pas."),
 Q("Laquelle de ces suites est bornée, mais pas monotone ?",["uₙ = (−1)ⁿ","uₙ = 1/n (pour n ≥ 1)","uₙ = n","uₙ = 2"],0,"(−1)ⁿ vaut 1, −1, 1, −1, … : elle reste entre −1 et 1 (bornée), mais elle monte et descend sans cesse. 1/n est décroissante, n est croissante, et la suite constante 2 est à la fois croissante et décroissante."),
 P("TD 2, exercice 1, sur papier",`<p>Écrire avec des quantificateurs :</p><p>(a) La suite (uₙ) est décroissante à partir d'un certain rang</p><p>(b) La suite (uₙ) est périodique à partir d'un certain rang</p><p>(c) La suite (uₙ) est minorée</p>`,`<span class="who">Corrigé officiel (Moodle), recopié</span><p><b>(a)</b> ∃N ∈ ℕ, ∀n ∈ ℕ, n ≥ N ⇒ uₙ₊₁ ≤ uₙ.<br>Forme plus courte, juste aussi : ∃N ∈ ℕ, ∀n ≥ N, uₙ₊₁ ≤ uₙ.</p><p><b>(b)</b> ∃N ∈ ℕ, ∃T ∈ ℕ*, ∀n ≥ N, u<sub>n+T</sub> = uₙ.<br>Le seul piège : écrire ∃T ∈ ℕ au lieu de ∃T ∈ ℕ*. Si T = 0 était accepté comme période, n'importe quelle suite serait périodique.</p><p><b>(c)</b> ∃m ∈ ℝ, ∀n ∈ ℕ, uₙ ≥ m.</p><p>Remarque du corrigé : inutile d'argumenter, la réponse directe suffit, car il s'agit seulement de traduire une phrase en symboles.</p>`,["(a) : « ∃N ∈ ℕ » est placé avant « ∀n »","(b) : la période T est prise dans ℕ* (pas T = 0), et il y a aussi un rang N","(c) : « ∃m ∈ ℝ » est placé avant « ∀n ∈ ℕ »"],5),
 K("Comment écrit-on avec des quantificateurs « la suite (uₙ) est majorée », « minorée », « bornée » ?","Majorée : ∃M, ∀n, uₙ ≤ M. Minorée : ∃m, ∀n, uₙ ≥ m. Bornée : ∃C, ∀n, |uₙ| ≤ C."),
 K("Comment écrit-on avec des quantificateurs qu'une propriété est vraie « à partir d'un certain rang » ?","On écrit ∃N₀ ∈ ℕ, ∀n ≥ N₀, … devant la propriété.")]},

/* ------------------------------------------------------------------ */
{id:"a-limite",t:"La limite d'une suite avec ε",min:15,goal:"Écrire la définition et prouver une limite avec ε, comme l'exercice 1 du CC1 2024-2025 (4 points).",steps:[
 Q("Que veut dire « la suite (uₙ) tend vers 0 » ?",["À partir d'un certain rang, uₙ est aussi près de 0 qu'on veut","uₙ = 0 pour un certain n, et la suite s'y arrête","uₙ diminue toujours, donc se rapproche de 0","uₙ devient négatif à partir d'un certain rang"],0,"C'est l'idée : pour toute précision ε, la suite finit par rester à moins de ε de 0. Une suite peut tendre vers 0 sans jamais valoir 0 (1/n), et une suite décroissante peut tendre vers 5 (5 + 1/n)."),
 L("La définition",`${box("(uₙ) converge vers ℓ  ⇔  ∀ε &gt; 0, ∃N ∈ ℕ, ∀n ≥ N, |uₙ − ℓ| ≤ ε")}<p>À lire : <b>quelle que soit la précision ε</b>, il existe un <b>rang N</b> à partir duquel <b>tous</b> les termes sont à distance au plus ε de ℓ. N dépend de ε : plus ε est petit, plus N est grand.</p><p>La limite est <b>unique</b>. Une suite qui converge est <b>bornée</b> (la réciproque est fausse : (−1)ⁿ).</p>`),
 Q("Dans la définition « ∀ε &gt; 0, ∃N ∈ ℕ, ∀n ≥ N, |uₙ − ℓ| ≤ ε », de quoi le rang N peut-il dépendre ?",["De ε","De n","De rien, c'est toujours le même N"],0,"« ∀ε, ∃N » : on choisit N après ε, donc N peut dépendre de ε."),
 L("Le modèle de rédaction",`<p>Pour prouver uₙ → ℓ :</p><ol><li><b>Majorer</b> |uₙ − ℓ| par quelque chose de simple qui tend vers 0, souvent 1/n.</li><li><b>« Soit ε &gt; 0. »</b> Choisir N = E(1/ε) + 1, de sorte que <b>1/ε &lt; N</b>.</li><li>Pour n ≥ N : |uₙ − ℓ| ≤ 1/n ≤ 1/N &lt; ε.</li><li>Conclure : ∀ε &gt; 0, ∃N ∈ ℕ, ∀n ≥ N, |uₙ − ℓ| ≤ ε, donc uₙ → ℓ.</li></ol><p>Si la majoration n'est pas 1/n, on résout au brouillon l'inégalité voulue pour trouver le rang.</p>`),
 S("CC1 2024-2025, exercice 1 (4 points)","L'énoncé : « En utilisant la définition de la limite d'une suite, montrez que lim<sub>n→+∞</sub> n·sin(n)/(n² + 2) = 0. »",[
  {w:"Majoration : pour n ≥ 1, |n sin(n)/(n² + 2)| ≤ n/(n² + 2) ≤ n/n² = 1/n.",why:"|sin(n)| ≤ 1, puis on agrandit la fraction en diminuant le dénominateur."},
  {w:"Soit ε &gt; 0. On pose N = E(1/ε) + 1 : alors 1/ε &lt; N.",why:"Le rang est choisi après ε."},
  {w:"Pour tout n ≥ N : |n sin(n)/(n² + 2) − 0| ≤ 1/n ≤ 1/N &lt; ε.",why:"1/n ≤ 1/N car n ≥ N, et 1/N &lt; ε car N &gt; 1/ε."},
  {w:"Donc ∀ε &gt; 0, ∃N ∈ ℕ, ∀n ≥ N, |n sin(n)/(n² + 2)| ≤ ε : la suite tend vers 0.",why:"On réécrit la définition, avec la limite."}]),
 Q("Pour prouver 1/√n → 0, quel rang N convient pour un ε &gt; 0 donné ?",["N = E(1/ε²) + 1","N = E(ε) + 1","N = 1","N = E(√ε) + 1"],0,"Au brouillon : 1/√n &lt; ε ⇔ √n &gt; 1/ε ⇔ n &gt; 1/ε². Avec N = E(1/ε²) + 1, on a N &gt; 1/ε² ; pour n ≥ N : √n ≥ √N &gt; 1/ε, donc 1/√n &lt; ε."),
 L("Tendre vers +∞",`${box("uₙ → +∞  ⇔  ∀A ∈ ℝ, ∃N ∈ ℕ, ∀n ≥ N, uₙ ≥ A")}<p>« Quel que soit le seuil A, la suite finit par rester au-dessus. » Une suite qui tend vers +∞ diverge (elle n'a pas de limite finie).</p>${box("uₙ → −∞  ⇔  ∀B ∈ ℝ, ∃N ∈ ℕ, ∀n ≥ N, uₙ ≤ B")}<p>Exemple : n² → +∞. Soit A ∈ ℝ. On pose N = max(0, E(A) + 1) : c'est un entier naturel, et N &gt; A. Pour n ≥ N : n² ≥ n ≥ N &gt; A.</p><p>À connaître : qⁿ → +∞ si q &gt; 1, qⁿ → 0 si |q| &lt; 1 ; nᵖ → +∞ si p &gt; 0, nᵖ → 0 si p &lt; 0.</p>`),
 Q("Quelle est la définition de « uₙ → −∞ » ?",["∀B ∈ ℝ, ∃N ∈ ℕ, ∀n ≥ N, uₙ ≤ B","∃B ∈ ℝ, ∃N ∈ ℕ, ∀n ≥ N, uₙ ≤ B","∃N ∈ ℕ, ∀B ∈ ℝ, ∀n ≥ N, uₙ ≤ B","∀B ∈ ℝ, ∀n ∈ ℕ, uₙ ≤ B"],0,"Comme +∞, avec un seuil B sous lequel la suite finit par rester. Avec ∃B, la suite finirait seulement sous un seuil fixé (majorée à partir d'un rang). Avec ∃N avant ∀B, le même rang devrait marcher pour tous les B : impossible."),
 P("TD 2, exercice 6, sur papier",`<p><b>En revenant aux définitions</b>, montrer que :</p><p>(a) (1/n²) converge vers 0</p><p>(b) (n³) tend vers +∞</p><p>(c) (−8n) tend vers −∞</p>`,`<span class="who">Corrigé officiel (manuscrit, Moodle), recopié</span><p>Rappel : pour tout réel x, l'entier E(x) + 1 vérifie E(x) + 1 &gt; x.</p><p><b>(a)</b> Soit ε &gt; 0. Posons N = E(√(1/ε)) + 1, où E est la partie entière. Ainsi N est un entier et, par définition de la partie entière, N ≥ √(1/ε), soit N² ≥ 1/ε, soit <b>1/N² ≤ ε</b>.<br>Soit n ∈ ℕ tel que n ≥ N. Alors, par croissance du carré et passage à l'inverse, 1/n² ≤ 1/N², et donc 1/n² ≤ ε.<br>La suite (1/n²) converge donc vers 0.</p><p><b>(b)</b> Soit A ∈ ℝ. Posons N = E(A<sup>1/3</sup>) + 1. Soit n ∈ ℕ tel que n ≥ N. Alors n ≥ E(A<sup>1/3</sup>) + 1, donc, par définition de la partie entière, n ≥ A<sup>1/3</sup>, donc <b>n³ ≥ A</b> (croissance de x ↦ x³).<br>D'où le fait que la suite (n³) tend vers +∞.</p><p><b>(c)</b> Soit A ∈ ℝ. Posons N = E(−A/8) + 1. Pour tout entier naturel n ≥ N : n ≥ N ≥ −A/8, donc <b>−8n ≤ A</b>.<br>La suite (−8n) tend donc vers −∞.</p><p>Deux précisions de ma part. A<sup>1/3</sup> est la racine cubique de A : le réel dont le cube vaut A (elle existe aussi quand A est négatif). Et dans (b) et (c), l'entier N ainsi posé peut être négatif (par exemple A = −1000 dans (b)). Pour être tranquille, écris N = max(0, E(A<sup>1/3</sup>) + 1) et N = max(0, E(−A/8) + 1). Autre preuve possible pour (b), comme dans l'exemple de la leçon : N = max(0, E(A) + 1), et n³ ≥ n ≥ N &gt; A.</p><p>Écrire « 1/n² → 0 car n² → +∞ » ne répond pas à la question : l'énoncé impose de revenir aux définitions.</p>`,["Les définitions sont utilisées (c'est ce que l'énoncé impose) : « Soit ε &gt; 0 » ou « Soit A ∈ ℝ » écrit d'abord","Le rang N est donné explicitement, en fonction de ε ou de A","La chaîne d'inégalités est écrite pour n ≥ N","Une phrase de conclusion pour chaque suite"],12),
 K("Quelle est la définition, avec ε, de « la suite (uₙ) converge vers ℓ » ?","∀ε &gt; 0, ∃N ∈ ℕ, ∀n ≥ N, |uₙ − ℓ| ≤ ε. N dépend de ε."),
 K("Quelles sont les étapes pour prouver, avec la définition, qu'une suite (uₙ) tend vers ℓ ?","Majorer |uₙ − ℓ| par 1/n ; « Soit ε &gt; 0 », N = E(1/ε) + 1 ; pour n ≥ N, |uₙ − ℓ| ≤ 1/n ≤ 1/N &lt; ε ; conclure.")]},

/* ------------------------------------------------------------------ */
{id:"a-lim-fonction",t:"Limite d'une fonction : les définitions",min:18,goal:"Écrire et utiliser les définitions avec ε, comme l'exercice 1 du CC1 2025-2026 (4 points).",steps:[
 Q("Que veut dire « f(x) tend vers ℓ quand x tend vers +∞ » ?",["f(x) est aussi près de ℓ qu'on veut dès que x est assez grand","f(+∞) = ℓ : on remplace x par +∞ dans la formule","f est croissante et se rapproche de ℓ sans l'atteindre","f(x) = ℓ dès que x est assez grand"],0,"Comme pour les suites, mais avec x réel au lieu de n entier. +∞ n'est pas un nombre : f(+∞) n'a pas de sens. Et f peut être décroissante, ou osciller, sans jamais atteindre ℓ.",{diag:false}),
 L("Les définitions",`<p>f est définie sur I ; x₀ est <b>adhérent</b> à I (on peut s'en approcher dans I).</p>${box("lim<sub>x→x₀</sub> f(x) = ℓ  ⇔  ∀ε &gt; 0, ∃η &gt; 0, ∀x ∈ I, |x − x₀| &lt; η ⇒ |f(x) − ℓ| &lt; ε")}${box("lim<sub>x→+∞</sub> f(x) = ℓ  ⇔  ∀ε &gt; 0, ∃α &gt; 0, ∀x ∈ I, x &gt; α ⇒ |f(x) − ℓ| &lt; ε")}${box("lim<sub>x→x₀</sub> f(x) = +∞  ⇔  ∀A &gt; 0, ∃η &gt; 0, ∀x ∈ I, |x − x₀| &lt; η ⇒ f(x) &gt; A")}<p>η (ou α) dépend de ε. Si x₀ ∈ I et que la limite existe, elle vaut f(x₀). Limite <b>à droite</b> : x ∈ [x₀, x₀ + η[ ; <b>épointée</b> : on enlève x₀.</p>`),
 Q("Quelle phrase est la définition de lim<sub>x→0</sub> f(x) = 1 ?",["∀ε &gt; 0, ∃η &gt; 0, ∀x ∈ ℝ, |x| &lt; η ⇒ |f(x) − 1| &lt; ε","∀ε &gt; 0, ∃η &gt; 0, ∀x ∈ ℝ, |x| &lt; ε ⇒ |f(x) − 1| &lt; η","∀ε &gt; 0, ∃η &gt; 0, ∀x ∈ ]1 − η, 1 + η[, |f(x)| &lt; ε"],0,"x près de 0 (à moins de η) ⇒ f(x) près de 1 (à moins de ε). Celle qui se termine par « |f(x) − 1| &lt; η » échange ε et η ; celle avec ]1 − η, 1 + η[ dit « f tend vers 0 en 1 » (CC1 2024-2025)."),
 L("Le modèle de rédaction en +∞",`<ol><li>Calculer et simplifier f(x) − ℓ.</li><li>« Soit ε &gt; 0. » Choisir α (en fonction de ε).</li><li>Pour x &gt; α : montrer |f(x) − ℓ| &lt; ε.</li><li>Conclure avec la définition complète.</li></ol><p>Exemple du cours : f(x) = x²/(x² + 1) tend vers 1 en +∞. f(x) − 1 = −1/(x² + 1), donc |f(x) − 1| = 1/(x² + 1). Soit ε &gt; 0, α = 1/√ε. Pour x &gt; α : x² &gt; 1/ε, donc x² + 1 &gt; 1/ε, donc |f(x) − 1| = 1/(x² + 1) &lt; ε.</p>`),
 L("Limites infinies, limites d'un seul côté",`<p>En un point x₀, f peut aussi tendre vers −∞, et on peut ne regarder qu'un seul côté de x₀.</p>${box("lim<sub>x→x₀</sub> f(x) = −∞  ⇔  ∀A &gt; 0, ∃η &gt; 0, ∀x ∈ I, |x − x₀| &lt; η ⇒ f(x) &lt; −A")}<ul><li><b>Limite épointée à droite</b> (on écrit x → x₀, x &gt; x₀) : on ne regarde que les x de ]x₀, x₀ + η[.</li><li><b>Limite épointée à gauche</b> (on écrit x → x₀, x &lt; x₀) : on ne regarde que les x de ]x₀ − η, x₀[.</li></ul><p>Exemple du cours : lim<sub>x→0, x&gt;0</sub> 1/x = +∞. Il faut montrer : ∀A &gt; 0, ∃η &gt; 0, ∀x ∈ ]0, η[, 1/x &gt; A. Soit A &gt; 0. On pose η = 1/A. Pour x ∈ ]0, η[ : 0 &lt; x &lt; 1/A, donc 1/x &gt; A.</p><p>De même, lim<sub>x→0, x&lt;0</sub> 1/x = −∞ : pour x ∈ ]−1/A, 0[, on a 1/x &lt; −A.</p>`),
 Q("Pour montrer que lim<sub>x→0, x&gt;0</sub> 1/x² = +∞, quel η choisir pour un A &gt; 0 donné ?",["η = 1/√A","η = A","η = 1/A²"],0,"Au brouillon : 1/x² &gt; A ⇔ x² &lt; 1/A ⇔ 0 &lt; x &lt; 1/√A. Donc, pour x ∈ ]0, 1/√A[, on a bien 1/x² &gt; A."),
 S("CC1 2025-2026, exercice 1 (4 points)",`L'énoncé : « Soit la fonction f : ℝ → ℝ définie par f(x) = (2x + 1)/x si x ≠ 0, et f(0) = 2. a) Calculer la limite de la fonction f en +∞. Démontrer ce résultat en utilisant la définition de la limite d'une fonction. b) La fonction f a-t-elle une limite en 0 ? Si oui, donnez sa valeur. Justifier ce résultat avec la méthode de votre choix. »`,[
  {w:"Pour x ≠ 0 : f(x) − 2 = (2x + 1)/x − 2 = 1/x.",why:"On simplifie l'écart à la limite."},
  {w:"Soit ε &gt; 0. On pose α = 1/ε. Pour tout réel x &gt; α : x &gt; 0 et 1/x &lt; 1/α = ε, donc |f(x) − 2| = 1/x &lt; ε.",why:"α est choisi pour que 1/x &lt; ε dès que x &gt; α."},
  {w:"Donc ∀ε &gt; 0, ∃α &gt; 0, ∀x ∈ ℝ, x &gt; α ⇒ |f(x) − 2| &lt; ε : lim<sub>x→+∞</sub> f(x) = 2.",why:"(a) On conclut avec la définition."},
  {w:"En 0 : pour x ≠ 0, f(x) = 2 + 1/x. Donc lim<sub>x→0, x&gt;0</sub> f(x) = +∞ et lim<sub>x→0, x&lt;0</sub> f(x) = −∞. Les limites à droite et à gauche sont différentes : f n'a pas de limite en 0.",why:"(b) C'est la justification du corrigé officiel : deux limites d'un seul côté différentes, donc pas de limite."}]),
 Q("On pose f(x) = (3x + 1)/(x − 7) pour x ≠ 7. Que vaut f(x) − 3, écrit avec un seul dénominateur ?",["22/(x − 7)","−20/(x − 7)","1/(x − 7)","(3x + 1)/(x − 7) − 3x"],0,"(3x + 1 − 3(x − 7))/(x − 7) = (3x + 1 − 3x + 21)/(x − 7) = 22/(x − 7) (TD 3, ex. 6)."),
 P("TD 3, exercice 7, sur papier",`<p>Montrer <b>en utilisant la définition de la limite</b> que la fonction f définie par x ↦ (x + 1)/(x − 1) tend vers 1 lorsque x tend vers +∞, puis que lim<sub>x→1, x&lt;1</sub> f(x) = −∞ et que lim<sub>x→1, x&gt;1</sub> f(x) = +∞.</p>`,`<span class="who">Corrigé écrit par moi (pas de corrigé officiel)</span><p>Pour x ≠ 1 : f(x) − 1 = (x + 1 − (x − 1))/(x − 1) = 2/(x − 1), donc <b>f(x) = 1 + 2/(x − 1)</b>.</p><p><b>Limite 1 en +∞.</b> Il faut montrer : ∀ε &gt; 0, ∃α &gt; 0, ∀x &gt; α, |f(x) − 1| &lt; ε.<br>Soit ε &gt; 0. Posons α = 1 + 2/ε. Soit x &gt; α. Alors x − 1 &gt; 2/ε &gt; 0, donc |f(x) − 1| = 2/(x − 1) &lt; ε.</p><p><b>Limite −∞ en 1, pour x &lt; 1.</b> Il faut montrer : ∀A &gt; 0, ∃η &gt; 0, ∀x ∈ ]1 − η, 1[, f(x) &lt; −A.<br>Soit A &gt; 0. Posons η = 2/(A + 1). Soit x ∈ ]1 − η, 1[. Alors 0 &lt; 1 − x &lt; 2/(A + 1), donc 2/(1 − x) &gt; A + 1. Or f(x) = 1 + 2/(x − 1) = 1 − 2/(1 − x). Donc f(x) &lt; 1 − (A + 1) = −A.</p><p><b>Limite +∞ en 1, pour x &gt; 1.</b> Il faut montrer : ∀A &gt; 0, ∃η &gt; 0, ∀x ∈ ]1, 1 + η[, f(x) &gt; A.<br>Soit A &gt; 0. Posons η = 2/A. Soit x ∈ ]1, 1 + η[. Alors 0 &lt; x − 1 &lt; 2/A, donc 2/(x − 1) &gt; A. Donc f(x) = 1 + 2/(x − 1) &gt; A.</p><p>Dire seulement « le dénominateur tend vers 0, donc f tend vers l'infini » ne répond pas à la question : l'énoncé impose la définition.</p>`,["La définition est utilisée à chaque fois (c'est ce que l'énoncé impose) : « Soit ε &gt; 0 » ou « Soit A &gt; 0 » écrit d'abord","f(x) − 1 simplifié en 2/(x − 1)","α, puis les deux η, sont donnés explicitement en fonction de ε ou de A","Le signe de x − 1 est dit à chaque fois (positif à droite de 1, négatif à gauche)"],15),
 K("Quelle est la définition, avec ε et η, de « f(x) tend vers ℓ quand x tend vers x₀ » ?","∀ε &gt; 0, ∃η &gt; 0, ∀x ∈ I, |x − x₀| &lt; η ⇒ |f(x) − ℓ| &lt; ε."),
 K("Quelle est la définition, avec ε, de « f(x) tend vers ℓ quand x tend vers +∞ » ?","∀ε &gt; 0, ∃α &gt; 0, ∀x ∈ I, x &gt; α ⇒ |f(x) − ℓ| &lt; ε. Modèle : simplifier f(x) − ℓ, « Soit ε &gt; 0 », α explicite, conclure.")]},

/* ------------------------------------------------------------------ */
{id:"a-calcul",t:"Calculer une limite de suite",min:13,goal:"Trouver une limite avec les opérations et lever les formes indéterminées (TD 2, ex. 5).",steps:[
 Q("Quelle est la limite de la suite (2n² − 6n + 1)/(−n³ + 2n − 2) quand n tend vers +∞ ?",["0","−2","+∞","2"],0,"Degré 2 en haut, 3 en bas : en factorisant par n³, on obtient (2/n − 6/n² + 1/n³)/(−1 + 2/n² − 2/n³) → 0/(−1) = 0."),
 L("Opérations sur les limites",`<p>Si uₙ → ℓ et vₙ → ℓ′ (finies) : uₙ + vₙ → ℓ + ℓ′, λuₙ → λℓ, uₙvₙ → ℓℓ′, |uₙ| → |ℓ|, et 1/uₙ → 1/ℓ si ℓ ≠ 0.</p><p>Avec des infinis : ℓ + ∞ = +∞, +∞ + ∞ = +∞, ℓ × ∞ = ±∞ si ℓ ≠ 0 (règle des signes), 1/∞ = 0, 1/(0⁺) = +∞. Ces écritures sont des raccourcis : « 1/∞ = 0 » veut dire « si uₙ → +∞ ou −∞, alors 1/uₙ → 0 », et 0⁺ veut dire « uₙ → 0 avec uₙ &gt; 0 ».</p><p><b>Formes indéterminées</b> (on ne peut rien dire sans transformer) : <b>+∞ − ∞</b>, <b>0 × ∞</b>, <b>∞/∞</b>, <b>0/0</b>.</p>`),
 Q("Deux suites vérifient uₙ → +∞ et vₙ → −∞. Que peut-on dire de la suite (uₙ + vₙ) ?",["Forme indéterminée : on ne peut pas conclure sans transformer","Elle tend vers 0 : +∞ et −∞ s'annulent","Elle tend vers +∞ : le premier terme l'emporte","Elle tend vers −∞ : le terme négatif l'emporte"],0,"+∞ − ∞ est une forme indéterminée : le résultat dépend des suites. Avec uₙ = n et vₙ = −n, la somme vaut 0. Avec uₙ = 2n et vₙ = −n, la somme vaut n, qui tend vers +∞. On ne peut donc rien dire sans plus d'informations."),
 L("Les trois outils",`<ul><li><b>Factoriser par le terme dominant</b> (celui qui grandit le plus vite), en haut et en bas : (2n² − 6n + 1)/(−n³ + 2n − 2) = [n²(2 − 6/n + 1/n²)] / [n³(−1 + 2/n² − 2/n³)] = (1/n) × (2 − 6/n + 1/n²)/(−1 + 2/n² − 2/n³). Or 1/n → 0, et la fraction → 2/(−1) = −2 : la limite est 0 × (−2) = 0.</li><li><b>Diviser par la plus grande puissance</b> : pour (2ⁿ − 3ⁿ)/(2ⁿ + 3ⁿ), on divise en haut et en bas par 3ⁿ. On obtient ((2/3)ⁿ − 1)/((2/3)ⁿ + 1) → (0 − 1)/(0 + 1) = −1, car (2/3)ⁿ → 0.</li><li><b>Quantité conjuguée</b> pour une différence de racines : √(n + 1) − √n = 1/(√(n + 1) + √n) → 0.</li></ul><p>Et quand ce n'est <b>pas</b> une forme indéterminée, on applique directement les règles : 5 − 3/n → 5, et n + 2ⁿ → +∞.</p>`),
 Q("Quelle est la limite de la suite n((1/3)ⁿ − 2) quand n tend vers +∞ ?",["−∞","0","−2","+∞"],0,"(1/3)ⁿ → 0, donc (1/3)ⁿ − 2 → −2, et n × (−2) → −∞ : ce n'est pas une forme indéterminée."),
 Q("Que fait la suite ((−2)ⁿ) quand n tend vers +∞ ?",["Elle n'a pas de limite : les termes pairs → +∞, les impairs → −∞","Elle tend vers +∞ : |(−2)ⁿ| = 2ⁿ → +∞","Elle tend vers 0 : les signes se compensent","Elle tend vers −∞ : la raison −2 est négative"],0,"Les termes changent de signe : 1, −2, 4, −8, 16… Les termes de rang pair valent (−2)²ᵏ = 4ᵏ, qui tend vers +∞. Ceux de rang impair valent (−2)²ᵏ⁺¹ = −2 · 4ᵏ, qui tend vers −∞. Les termes de rang pair et ceux de rang impair n'ont pas la même limite : (−2)ⁿ n'a pas de limite (TD 2, ex. 5 c). |uₙ| → +∞ ne suffit pas pour uₙ → +∞ : il faut aussi le signe."),
 P("TD 2, exercice 5 : (a), (d), (e), (g) et (h), sur papier",`<p>Étudier les limites éventuelles des suites suivantes :</p><p>(a) uₙ = 3n − 7 + 2ⁿ</p><p>(d) uₙ = √(3n² − n)</p><p>(e) uₙ = 5 + 2/n + 1/2ⁿ</p><p>(g) uₙ = (n + 1)/√(n³ − 2n + 1)</p><p>(h) uₙ = (aⁿ − bⁿ)/(aⁿ + bⁿ) où 0 ≤ a &lt; b</p><p>Les suites (b), (c) et (f) du même exercice ont été vues dans cette leçon.</p>`,`<span class="who">(a), (e), (g) : corrigé officiel (manuscrit, Moodle), recopié. (d), (h) : écrits par moi</span><p><b>(a)</b> 3n → +∞ et 2ⁿ → +∞ (car 2 &gt; 1), donc <b>uₙ → +∞</b> par somme. Ce n'est pas une forme indéterminée.</p><p><b>(d)</b> Pour n ≥ 1 : 3n² − n = n²(3 − 1/n) et 3 − 1/n ≥ 2, donc uₙ = n√(3 − 1/n) ≥ √2 × n. Comme √2 × n → +∞, <b>uₙ → +∞</b> par comparaison.</p><p><b>(e)</b> 2/n → 0 et 1/2ⁿ → 0, donc <b>uₙ → 5</b> par somme.</p><p><b>(g)</b> On factorise par les termes dominants : uₙ = [n(1 + 1/n)] / [n<sup>3/2</sup>√(1 − 2/n² + 1/n³)] = (1/√n) × (1 + 1/n)/√(1 − 2/n² + 1/n³). Or 1/√n → 0 ; 1 + 1/n → 1 ; √(1 − 2/n² + 1/n³) → √1 = 1 par continuité de la racine carrée. Par produit et quotient (bien défini) de limites, <b>uₙ → 0</b>.</p><p><b>(h)</b> Comme b &gt; 0, on divise en haut et en bas par bⁿ : uₙ = ((a/b)ⁿ − 1)/((a/b)ⁿ + 1). Or 0 ≤ a/b &lt; 1, donc (a/b)ⁿ → 0. Par quotient, <b>uₙ → (0 − 1)/(0 + 1) = −1</b>.</p>`,["Pour chaque suite : forme indéterminée, ou pas ?","(d), (g) : la factorisation par le terme dominant est écrite","(h) : division par bⁿ, et (a/b)ⁿ → 0 justifié par 0 ≤ a/b &lt; 1","La limite de chaque morceau est annoncée, puis « par somme », « par produit », « par quotient »"],12),
 K("Quelles sont les quatre formes indéterminées dans un calcul de limite ? Que fait-on pour les lever ?","+∞ − ∞, 0 × ∞, ∞/∞, 0/0. On transforme : factoriser par le terme dominant, diviser par la plus grande puissance, quantité conjuguée."),
 K("Quelle est la limite de la suite (qⁿ), selon la valeur du réel q ?","→ +∞ si q &gt; 1 ; → 0 si |q| &lt; 1 ; = 1 si q = 1 ; pas de limite si q ≤ −1.")]},

/* ------------------------------------------------------------------ */
{id:"a-comparaison",t:"Comparaison et gendarmes",min:16,goal:"Utiliser les inégalités pour trouver une limite, et éviter les pièges du vrai/faux (TD 2, ex. 9).",steps:[
 Q("Si uₙ &lt; vₙ pour tout n et que les deux convergent, a-t-on lim uₙ &lt; lim vₙ ?",["Non, seulement lim uₙ ≤ lim vₙ","Oui, toujours","On ne peut rien dire"],0,"uₙ = 0 &lt; vₙ = 1/n, et pourtant les deux limites valent 0 : les inégalités strictes deviennent larges.",{diag:false}),
 L("Passage à la limite et signe",`<ul><li><b>Passage à la limite</b> : si uₙ ≤ vₙ à partir d'un rang et que les deux convergent, alors lim uₙ ≤ lim vₙ. Avec « &lt; », on obtient seulement ≤.</li><li><b>Signe</b> : si uₙ → ℓ &gt; 0, alors uₙ &gt; 0 à partir d'un certain rang. Si uₙ ≥ 0 à partir d'un rang, alors ℓ ≥ 0.</li></ul><p>Exemple (TD 2, ex. 9) : si uₙ → ℓ, vₙ → ℓ′ et ℓ &lt; ℓ′, alors uₙ &lt; vₙ à partir d'un certain rang (prendre ε = (ℓ′ − ℓ)/3).</p>`),
 Q("Une suite (uₙ) vérifie uₙ &gt; 0 pour tout n et converge vers ℓ. Que peut-on dire de ℓ ?",["ℓ ≥ 0","ℓ &gt; 0","ℓ = 0","On ne peut rien dire"],0,"La positivité passe à la limite en devenant large : uₙ = 1/n &gt; 0 tend vers 0."),
 L("Le théorème des gendarmes",`${box("uₙ ≤ vₙ ≤ wₙ (à partir d'un rang), uₙ → ℓ et wₙ → ℓ  ⇒  vₙ converge et vₙ → ℓ")}<p>Version infinie : si uₙ ≤ vₙ et uₙ → +∞, alors vₙ → +∞ (et si vₙ → −∞, alors uₙ → −∞).</p><p>Très utile avec sin et cos, qui sont entre −1 et 1 : −1/n ≤ sin(n)/n ≤ 1/n, donc sin(n)/n → 0. Plus généralement, <b>|vₙ − ℓ| ≤ aₙ avec aₙ → 0</b> suffit.</p>`),
 Q("Quelle est la limite de la suite cos(n)/√n (pour n ≥ 1) ?",["0 : |cos(n)/√n| ≤ 1/√n, et 1/√n → 0","1 : cos(n) se rapproche de 1 quand n grandit","Pas de limite : cos(n) oscille entre −1 et 1","+∞ : √n → +∞ l'emporte sur cos(n)"],0,"cos(n) oscille, mais il reste entre −1 et 1, et on le divise par √n, qui tend vers +∞ : −1/√n ≤ cos(n)/√n ≤ 1/√n. Les deux gendarmes tendent vers 0, donc la suite aussi. cos(n) ne se rapproche pas de 1 : il continue d'osciller. Mais osciller n'empêche pas de converger quand les oscillations deviennent aussi petites qu'on veut. Et √n est au dénominateur : il rend la suite petite, pas grande."),
 Q("Quelle est la limite de la suite n + sin(n) ?",["+∞ : n + sin(n) ≥ n − 1, et n − 1 → +∞","Pas de limite : sin(n) oscille, donc la somme aussi","+∞ seulement si sin(n) ≥ 0 ; sinon on ne peut rien dire"],0,"sin(n) ≥ −1 pour tout n, donc n + sin(n) ≥ n − 1. La suite est au-dessus d'une suite qui tend vers +∞ : elle tend vers +∞ (version infinie des gendarmes). L'oscillation de sin(n), entre −1 et 1, est négligeable devant n. Et le signe de sin(n) ne compte pas : la minoration par n − 1 est vraie dans tous les cas."),
 P("TD 2, exercice 11, sur papier",`<p>On veut démontrer un résultat de croissance comparée : (uₙ)<sub>n∈ℕ</sub> définie par uₙ = n/2ⁿ tend vers 0.</p><p>On définit, pour n &gt; 0, vₙ = uₙ₊₁/uₙ.</p><p>(a) Démontrer que (vₙ) converge vers 1/2.</p><p>(b) <b>En déduire</b> qu'il existe n₀ ∈ ℕ tel que ∀n ≥ n₀, uₙ₊₁/uₙ ≤ 3/4.</p><p>(c) Démontrer que ∀n ≥ n₀, uₙ ≤ (3/4)<sup>n−n₀</sup> u<sub>n₀</sub>.</p><p>(d) <b>En déduire</b> que (uₙ) tend vers 0.</p>`,`<span class="who">Corrigé officiel (manuscrit, Moodle), recopié</span><p><b>(a)</b> Développons l'expression : vₙ = uₙ₊₁/uₙ = [(n + 1)/2ⁿ⁺¹] × [2ⁿ/n] = (1/2) × (n + 1)/n. Or (n + 1)/n = 1 + 1/n → 1, donc <b>lim vₙ = 1/2</b> par produit.</p><p><b>(b)</b> Comme (vₙ) converge vers 1/2, il existe un rang n₀ ∈ ℕ tel que, pour tout n ≥ n₀, |vₙ − 1/2| ≤ 1/4 (c'est la définition de la limite, avec ε = 1/4). Soit −1/4 ≤ uₙ₊₁/uₙ − 1/2 ≤ 1/4, soit <b>1/4 ≤ uₙ₊₁/uₙ ≤ 3/4</b>.<br>(« En déduire » demande d'utiliser le (a). Le calcul direct (n + 1)/(2n) ≤ 3/4 ⇔ n ≥ 2 donne aussi n₀ = 2, mais ce n'est pas ce que la question attend.)</p><p><b>(c)</b> Montrons par récurrence la propriété (Pₙ) : « uₙ ≤ (3/4)<sup>n−n₀</sup> u<sub>n₀</sub> » pour tout n ≥ n₀.<br><b>Initialisation.</b> u<sub>n₀</sub> = (3/4)⁰ u<sub>n₀</sub> : (P<sub>n₀</sub>) est vraie.<br><b>Hérédité.</b> Soit n ≥ n₀ tel que (Pₙ) est vraie. D'après la question précédente, uₙ₊₁/uₙ ≤ 3/4, donc uₙ₊₁ ≤ (3/4)uₙ (car uₙ &gt; 0). Or, d'après (Pₙ), uₙ ≤ (3/4)<sup>n−n₀</sup> u<sub>n₀</sub>. Donc uₙ₊₁ ≤ (3/4) × (3/4)<sup>n−n₀</sup> u<sub>n₀</sub> = (3/4)<sup>n+1−n₀</sup> u<sub>n₀</sub>. D'où (Pₙ₊₁).<br><b>Conclusion.</b> D'après le théorème de récurrence, (Pₙ) est vraie pour tout n ≥ n₀.</p><p><b>(d)</b> Puisque 0 &lt; 3/4 &lt; 1, (3/4)<sup>n−n₀</sup> → 0. Comme 0 &lt; uₙ ≤ (3/4)<sup>n−n₀</sup> u<sub>n₀</sub> pour tout n ≥ n₀, <b>lim uₙ = 0</b> par encadrement (théorème des gendarmes).</p>`,["(a) : vₙ simplifié en (1/2) × (n + 1)/n","(b) : le résultat du (a) est utilisé, avec la définition de la limite et un ε précis (ε = 1/4)","(c) : récurrence à partir du rang n₀ (initialisation en n₀, hérédité, conclusion)","(d) : l'encadrement de uₙ est écrit, et le théorème des gendarmes est cité"],15),
 K("Que dit le théorème des gendarmes pour trois suites telles que uₙ ≤ vₙ ≤ wₙ ?","uₙ ≤ vₙ ≤ wₙ à partir d'un rang, uₙ et wₙ → ℓ : alors vₙ → ℓ. Version infinie : uₙ ≤ vₙ et uₙ → +∞ donnent vₙ → +∞."),
 K("Si uₙ &lt; vₙ pour tout n et que les deux suites convergent, que peut-on dire de leurs limites ?","uₙ &lt; vₙ donne seulement lim uₙ ≤ lim vₙ (les inégalités deviennent larges à la limite).")]},

/* ------------------------------------------------------------------ */
{id:"a-monotone",t:"Suites monotones et suites récurrentes",min:17,goal:"Rédiger l'étude complète d'une suite récurrente, comme l'exercice 2 du CC1 2024-2025 (6 points).",steps:[
 Q("Que peut-on dire d'une suite croissante et majorée ?",["Elle converge","Elle tend vers +∞","Elle peut diverger"],0,"C'est le théorème de la limite monotone : elle converge (vers la borne sup de ses valeurs). Elle ne peut pas tendre vers +∞ : tous ses termes restent sous le majorant. Et « elle peut diverger » est faux : croissante et majorée suffit toujours pour converger."),
 L("Théorème de la limite monotone",`<ul><li>(uₙ) croissante et <b>majorée</b> ⇒ elle <b>converge</b>. Croissante non majorée ⇒ elle tend vers +∞.</li><li>(uₙ) décroissante et <b>minorée</b> ⇒ elle <b>converge</b>. Décroissante non minorée ⇒ elle tend vers −∞.</li></ul><p>Ce théorème donne l'<b>existence</b> de la limite, pas sa valeur. Pour la valeur d'une suite uₙ₊₁ = f(uₙ), on <b>passe à la limite</b> dans la relation : ℓ = f(ℓ) (quand f est « gentille » en ℓ), puis on choisit la bonne solution grâce aux bornes.</p>`),
 Q("Une suite (uₙ) est décroissante et vérifie uₙ ≥ √2 pour tout n. Que peut-on dire de cette suite ?",["Elle converge, et sa limite ℓ vérifie ℓ ≥ √2","Elle diverge : une suite décroissante tend vers −∞","Elle converge, et sa limite vaut forcément √2"],0,"Décroissante et minorée (par √2) : elle converge, c'est le théorème de la limite monotone. La minoration passe à la limite : ℓ ≥ √2. Mais rien ne dit que ℓ = √2 : la suite uₙ = 2 + 1/n est décroissante, vérifie uₙ ≥ √2, et tend vers 2. Et une suite décroissante ne tend vers −∞ que si elle n'est pas minorée."),
 Q("Une suite (uₙ) est décroissante, et une suite (vₙ) vérifie vₙ ≥ 0 pour tout n. Si vₙ &lt; uₙ pour tout n, la suite (uₙ) converge-t-elle ?",["Oui : elle est décroissante et minorée par 0","Non : une suite décroissante tend vers −∞","Seulement si (vₙ) converge : (uₙ) reste au-dessus d'elle","Non : il faudrait qu'elle soit aussi majorée"],0,"uₙ &gt; vₙ ≥ 0 : (uₙ) est minorée par 0. Décroissante et minorée, elle converge (CC1 2025-2026, partie 2, question 2a : « vraie »). Une suite décroissante est déjà majorée (par u₀) : il lui faut seulement un minorant. (vₙ) n'a pas besoin de converger."),
 L("La méthode en 4 étapes",`<ol><li><b>Bornes par récurrence</b> : P(n) : « … ≤ uₙ ≤ … ». Initialisation P(0), hérédité P(n) ⇒ P(n + 1), conclusion.</li><li><b>Monotonie</b> : signe de uₙ₊₁ − uₙ, ou uₙ₊₁/uₙ comparé à 1 (termes &gt; 0), en utilisant les bornes.</li><li><b>Convergence</b> : monotone et bornée du bon côté.</li><li><b>Valeur</b> : ℓ = f(ℓ), on résout, et on élimine les solutions incompatibles avec les bornes.</li></ol>`),
 S("CC1 2024-2025, exercice 2, question 2","L'énoncé : « On considère la suite (uₙ) définie par u₀ = 2 et uₙ₊₁ = uₙ/2 + 1/uₙ, ∀n ∈ ℕ. a) Montrez que ∀n ∈ ℕ, uₙ &gt; √2. b) Montrez que la suite (uₙ) est strictement décroissante. c) Montrez que la suite (uₙ) converge vers une limite que vous calculerez. »",[
  {w:"P(n) : uₙ &gt; √2. P(0) : u₀ = 2 &gt; √2.",why:"Initialisation."},
  {w:"Hérédité : si uₙ &gt; √2, alors uₙ₊₁ = (uₙ² + 2)/(2uₙ). Or (uₙ − √2)² &gt; 0 donne uₙ² + 2 &gt; 2√2 uₙ ; en divisant par 2uₙ &gt; 0 : uₙ₊₁ &gt; √2.",why:"L'astuce : un carré non nul est strictement positif."},
  {w:"Monotonie : uₙ₊₁/uₙ = 1/2 + 1/uₙ² &lt; 1/2 + 1/2 = 1 (car uₙ² &gt; 2), et uₙ &gt; 0 : uₙ₊₁ &lt; uₙ.",why:"Termes positifs : on compare le quotient à 1."},
  {w:"(uₙ) est strictement décroissante et minorée par √2 : elle converge vers ℓ ≥ √2.",why:"Théorème de la limite monotone."},
  {w:"Passage à la limite : ℓ = ℓ/2 + 1/ℓ, donc ℓ/2 = 1/ℓ, ℓ² = 2 ; comme ℓ ≥ √2 &gt; 0 : ℓ = √2.",why:"On élimine −√2 grâce à la minoration."}]),
 Q("Dans le passage à la limite, pourquoi garde-t-on ℓ = √2 et pas −√2 ?",["Parce que ℓ ≥ √2, la minoration passant à la limite","Parce que −√2 n'est pas un réel : une racine est positive","Parce que la suite est décroissante, donc sa limite est positive","Parce qu'une limite de suite est toujours positive"],0,"L'équation ℓ² = 2 a deux solutions, √2 et −√2. Mais tous les termes vérifient uₙ &gt; √2, et une inégalité passe à la limite (en devenant large) : ℓ ≥ √2. Donc ℓ ne peut pas être −√2 : ℓ = √2. −√2 est bien un réel, et une limite peut être négative : seule la minoration uₙ &gt; √2 permet de choisir.",{diag:false,ctx:true}),
 P("TD 2, exercice 7, sur papier",`<p>Soit (uₙ) la suite définie par u₀ ∈ ]0, 1] et par ∀n ∈ ℕ, uₙ₊₁ = uₙ/2 + uₙ²/4.</p><p>(a) Démontrer que ∀n ∈ ℕ, 0 &lt; uₙ ≤ 1.</p><p>(b) Démontrer que la suite (uₙ) est monotone.</p><p>(c) En déduire qu'elle est convergente.</p>`,`<span class="who">Corrigé officiel (manuscrit, Moodle), recopié</span><p><b>(a)</b> On va démontrer ce résultat par récurrence.<br><b>Initialisation.</b> Par hypothèse, 0 &lt; u₀ ≤ 1.<br><b>Hérédité.</b> Supposons qu'il existe un entier naturel n tel que la propriété soit vraie au rang n : 0 &lt; uₙ ≤ 1. Ainsi 0 &lt; uₙ/2 ≤ 1/2 et 0 &lt; uₙ²/4 ≤ 1/4. Donc 0 &lt; uₙ₊₁ = uₙ/2 + uₙ²/4 ≤ 3/4, et 3/4 ≤ 1.<br>La propriété est initialisée et héréditaire. Ainsi <b>∀n ∈ ℕ, 0 &lt; uₙ ≤ 1</b>.</p><p><b>(b)</b> Soit n un entier naturel. uₙ₊₁ − uₙ = −uₙ/2 + uₙ²/4 = uₙ(uₙ − 2)/4 &lt; 0, car uₙ &gt; 0 et uₙ − 2 &lt; 0 (d'après (a)). Donc <b>la suite (uₙ) est décroissante</b>.</p><p><b>(c)</b> La suite (uₙ) est minorée par 0 et décroissante. <b>Cette suite est donc convergente</b> (théorème de la limite monotone).</p><p>Pour aller plus loin (ce n'est pas demandé, et ce n'est pas dans le corrigé officiel) : la limite ℓ vérifie ℓ = ℓ/2 + ℓ²/4, c'est-à-dire ℓ(ℓ − 2) = 0. Comme 0 ≤ ℓ ≤ 1, on trouve ℓ = 0.</p>`,["(a) : récurrence complète (initialisation, hérédité, conclusion)","(b) : uₙ₊₁ − uₙ factorisé, et son signe justifié avec le (a)","(c) : « décroissante et minorée par 0 », donc convergente"],12),
 K("Que dit le théorème de la limite monotone pour une suite croissante ? Et pour une suite décroissante ?","Croissante majorée ⇒ converge ; décroissante minorée ⇒ converge. Sinon, elle tend vers ±∞."),
 K("Quelles sont les étapes pour étudier une suite définie par uₙ₊₁ = f(uₙ) ?","1. Bornes par récurrence. 2. Monotonie (différence ou quotient). 3. Convergence (monotone bornée). 4. ℓ = f(ℓ), et les bornes choisissent la solution.")]},

/* ------------------------------------------------------------------ */
{id:"a-adjacentes",t:"Suites adjacentes",min:13,goal:"Reconnaître deux suites adjacentes et trouver leur limite commune, comme l'exercice 2 du CC1 2025-2026 (6 points).",steps:[
 Q("Deux suites se rapprochent l'une de l'autre (leur différence tend vers 0) ; l'une est croissante, l'autre décroissante. Que peut-on dire de leurs limites ?",["Elles ont la même limite","Elles divergent toutes les deux","Elles ont des limites différentes"],0,"L'une monte, l'autre descend, et l'écart entre elles tend vers 0 : coincées l'une contre l'autre, elles finissent au même endroit. C'est le théorème des suites adjacentes, que cette leçon énonce : les deux suites convergent, et vers la même limite."),
 L("Le théorème",`<p>Si :</p><ul><li>(uₙ) est <b>croissante</b>,</li><li>(vₙ) est <b>décroissante</b>,</li><li>∀n, <b>uₙ ≤ vₙ</b>,</li><li><b>vₙ − uₙ → 0</b>,</li></ul><p>alors (uₙ) et (vₙ) <b>convergent vers la même limite</b> ℓ (on dit qu'elles sont adjacentes), et uₙ ≤ ℓ ≤ vₙ pour tout n.</p><p>Pour trouver ℓ, on cherche une quantité qui ne bouge pas (uₙ + vₙ constante, par exemple).</p>`),
 Q("Que faut-il vérifier pour dire que (uₙ) et (vₙ) sont adjacentes ?",["L'une croissante, l'autre décroissante, uₙ ≤ vₙ et vₙ − uₙ → 0","Seulement uₙ ≤ vₙ et vₙ − uₙ → 0","Qu'elles sont bornées et toutes les deux monotones","L'une croissante, l'autre décroissante, et uₙ ≤ vₙ"],0,"Les quatre conditions du théorème : (uₙ) est croissante ; (vₙ) est décroissante ; uₙ ≤ vₙ pour tout n ; et vₙ − uₙ tend vers 0. Il faut les vérifier toutes les quatre avant de conclure."),
 S("CC1 2025-2026, exercice 2 (6 points)",`L'énoncé : « Soit (uₙ) et (vₙ) deux suites définies par u₀ = 1 et v₀ = 3 et, pour n ≥ 0, uₙ₊₁ = (3uₙ + vₙ)/4 et vₙ₊₁ = (uₙ + 3vₙ)/4. a) Déterminer u₁, u₂, v₁, v₂. b) Démontrer que la suite (uₙ + vₙ) est une suite constante. c) Démontrer que : ∀n ∈ ℕ, vₙ₊₁ − uₙ₊₁ = 1/2ⁿ. d) Démontrer que : ∀n ∈ ℕ, uₙ ≤ uₙ₊₁ ≤ vₙ₊₁ ≤ vₙ. e) Déduire de cette étude que les suites (uₙ) et (vₙ) sont convergentes et donner leur limite. »`,[
  {w:"u₁ = 3/2, v₁ = 5/2, u₂ = 7/4, v₂ = 9/4.",why:"(a) On applique les formules."},
  {w:"uₙ₊₁ + vₙ₊₁ = (4uₙ + 4vₙ)/4 = uₙ + vₙ : la suite (uₙ + vₙ) est constante, égale à u₀ + v₀ = 4.",why:"(b) La quantité qui ne bouge pas."},
  {w:"vₙ₊₁ − uₙ₊₁ = (2vₙ − 2uₙ)/4 = (vₙ − uₙ)/2, donc vₙ − uₙ = (v₀ − u₀)/2ⁿ = 2/2ⁿ, soit vₙ₊₁ − uₙ₊₁ = 1/2ⁿ.",why:"(c) L'écart est divisé par 2 à chaque étape."},
  {w:"Récurrence P(n) : uₙ ≤ uₙ₊₁ ≤ vₙ₊₁ ≤ vₙ. P(0) : 1 ≤ 3/2 ≤ 5/2 ≤ 3. Hérédité : uₙ₊₂ − uₙ₊₁ = (vₙ₊₁ − uₙ₊₁)/4 ≥ 0 et vₙ₊₂ − vₙ₊₁ = (uₙ₊₁ − vₙ₊₁)/4 ≤ 0 ; et vₙ₊₂ − uₙ₊₂ = 1/2ⁿ⁺¹ ≥ 0.",why:"(d) Les trois inégalités se transmettent."},
  {w:"(uₙ) croissante, (vₙ) décroissante, uₙ ≤ vₙ, vₙ − uₙ = 2/2ⁿ → 0 : elles sont adjacentes, de limite commune ℓ. Comme uₙ + vₙ = 4, 2ℓ = 4 : ℓ = 2.",why:"(e) Le théorème, puis la quantité constante donne ℓ."}]),
 Q("Deux suites adjacentes (uₙ) et (vₙ) vérifient uₙ + vₙ = 4 pour tout n. Quelle est leur limite commune ℓ ?",["ℓ = 2 : à la limite, uₙ + vₙ = 4 devient ℓ + ℓ = 4","ℓ = 4 : la somme vaut toujours 4, donc la limite aussi","On ne peut pas la trouver sans connaître u₀ et v₀"],0,"Deux suites adjacentes ont la même limite ℓ. On passe à la limite dans l'égalité uₙ + vₙ = 4 : uₙ → ℓ et vₙ → ℓ, donc ℓ + ℓ = 4, soit ℓ = 2. Ce n'est pas 4 : 4 est la limite de la somme, pas celle de chaque suite. Et u₀, v₀ ne servent plus : l'égalité, vraie à tous les rangs, suffit. C'est la fin de l'exercice 2 du CC1 2025-2026."),
 P("TD 2, exercice 8, sur papier",`<p>Soient (xₙ) et (yₙ) deux suites réelles définies par 0 &lt; x₀ &lt; y₀ et, ∀n ∈ ℕ, xₙ₊₁ = xₙ²/(xₙ + yₙ) et yₙ₊₁ = yₙ²/(xₙ + yₙ).</p><p>(a) Montrer que (xₙ − yₙ) est une suite constante.</p><p>(b) <b>En déduire</b> que (xₙ) est décroissante et (yₙ) décroissante.</p><p>(c) Montrer que les deux suites sont convergentes, et calculer leurs limites respectives.</p>`,`<span class="who">Corrigé officiel (deux versions manuscrites sur Moodle), recopié ; la récurrence « termes strictement positifs », que le corrigé laisse au lecteur, est écrite par moi</span><p><b>Avant tout : les termes sont strictement positifs.</b> Par récurrence : x₀ &gt; 0 et y₀ &gt; 0 ; et si xₙ &gt; 0 et yₙ &gt; 0, alors xₙ + yₙ &gt; 0, donc xₙ₊₁ = xₙ²/(xₙ + yₙ) &gt; 0 et yₙ₊₁ = yₙ²/(xₙ + yₙ) &gt; 0. (En particulier, on ne divise jamais par 0.)</p><p><b>(a)</b> Posons C = x₀ − y₀. Montrons par récurrence que, pour tout n ∈ ℕ, la propriété (Pₙ) : « xₙ − yₙ = C » est vraie.<br><b>Initialisation.</b> (P₀) est vraie par définition de C.<br><b>Hérédité.</b> Soit n ∈ ℕ tel que (Pₙ) est vraie. Par définition des deux suites : xₙ₊₁ − yₙ₊₁ = xₙ²/(xₙ + yₙ) − yₙ²/(xₙ + yₙ) = (xₙ² − yₙ²)/(xₙ + yₙ) = (xₙ − yₙ)(xₙ + yₙ)/(xₙ + yₙ) (identité remarquable) = xₙ − yₙ = C (par (Pₙ)).<br><b>Conclusion.</b> D'après le théorème de récurrence, <b>xₙ − yₙ = C pour tout n ∈ ℕ</b>.</p><p><b>(b)</b> Pour tout n ∈ ℕ, xₙ = C + yₙ : les deux suites ont donc la même monotonie. Or xₙ₊₁/xₙ = xₙ/(xₙ + yₙ) ∈ ]0, 1[ pour tout n ∈ ℕ, puisque 0 &lt; xₙ &lt; xₙ + yₙ. Donc xₙ₊₁ &lt; xₙ : <b>(xₙ) décroît, et par conséquent (yₙ) décroît</b>.</p><p><b>(c)</b> Les deux suites sont décroissantes et minorées (par 0), donc <b>elles convergent</b>, par le théorème de la limite monotone. Notons ℓ₁ = lim xₙ et ℓ₂ = lim yₙ ; on a ℓ₁ ≥ 0 et ℓ₂ ≥ 0.<br>En passant à la limite dans xₙ − yₙ = C : ℓ₁ − ℓ₂ = C &lt; 0, donc ℓ₂ = ℓ₁ + (y₀ − x₀) &gt; 0, et ℓ₁ + ℓ₂ &gt; 0.<br>En passant à la limite dans xₙ₊₁ = xₙ²/(xₙ + yₙ) : ℓ₁ = ℓ₁²/(ℓ₁ + ℓ₂). Donc ℓ₁(ℓ₁ + ℓ₂) = ℓ₁², soit ℓ₁ℓ₂ = 0. Donc ℓ₁ = 0 ou ℓ₂ = 0 ; or ℓ₂ &gt; 0.<br>Donc <b>ℓ₁ = 0 et ℓ₂ = −C = y₀ − x₀</b>.</p><p>Remarque : ces deux suites ne sont pas adjacentes (elles descendent toutes les deux). C'est le théorème de la limite monotone qui sert, avec la même idée que dans l'exemple : une quantité constante, ici xₙ − yₙ.</p>`,["Les termes sont strictement positifs (récurrence) : on ne divise jamais par 0","(a) : récurrence, avec xₙ² − yₙ² = (xₙ − yₙ)(xₙ + yₙ)","(b) : le résultat du (a) est utilisé (les deux suites ont la même monotonie)","(c) : décroissantes et minorées par 0, donc convergentes, puis passage à la limite","(c) : ℓ₁ = 0 et ℓ₂ = y₀ − x₀, avec la raison pour laquelle ce n'est pas ℓ₂ qui est nul"],15),
 K("Quand dit-on que deux suites (uₙ) et (vₙ) sont adjacentes ? Que peut-on en conclure ?","(uₙ) croissante, (vₙ) décroissante, uₙ ≤ vₙ, vₙ − uₙ → 0 : elles convergent vers la même limite ℓ, et uₙ ≤ ℓ ≤ vₙ."),
 K("Comment trouver la limite commune de deux suites adjacentes définies par récurrence ?","Chercher une quantité qui ne change pas d'un rang au suivant, par exemple uₙ + vₙ = constante, puis passer à la limite dans cette égalité : si uₙ + vₙ = 4 pour tout n, alors 2ℓ = 4.")]},

/* ------------------------------------------------------------------ */
{id:"a-extraites",t:"Suites extraites et valeurs d'adhérence",min:13,p:2,goal:"Prouver qu'une suite diverge avec deux sous-suites (TD 2, ex. 10).",steps:[
 Q("Pour une suite (uₙ), que désigne la suite (u₂ₙ) ?",["La suite des termes de rang pair : u₀, u₂, u₄, …","La suite multipliée par 2 : 2u₀, 2u₁, 2u₂, …","Le terme u₂ répété : u₂, u₂, u₂, …","La suite des termes de rang impair : u₁, u₃, u₅, …"],0,"(u₂ₙ) est la suite extraite des termes de rang pair : on remplace n par 2n, ce qui garde u₀, u₂, u₄… Par exemple, si uₙ = (−1)ⁿ, alors u₂ₙ = (−1)²ⁿ = 1 pour tout n."),
 L("Suites extraites",`<p>Une <b>extraction</b> est une application φ : ℕ → ℕ strictement croissante. La suite (u<sub>φ(n)</sub>) est une <b>suite extraite</b> (sous-suite) : on garde certains termes, dans l'ordre. Exemples : (u₂ₙ) et (u₂ₙ₊₁).</p><ul><li>Si uₙ → ℓ (fini ou infini), <b>toute</b> suite extraite tend vers ℓ.</li><li>Donc : si deux suites extraites ont des limites <b>différentes</b>, (uₙ) <b>diverge</b>.</li></ul><p>Exemple : ((−1)ⁿ) : les termes pairs valent 1, les impairs −1 ; elle diverge.</p>`),
 Q("Les deux suites extraites (u₂ₙ) et (u₂ₙ₊₁) convergent. La suite (uₙ) converge-t-elle forcément ?",["Non : ((−1)ⁿ) est un contre-exemple","Oui : à elles deux, elles contiennent tous les termes","Oui, si en plus (uₙ) est bornée"],0,"Il faut en plus que les deux limites soient égales (TD 2, ex. 10b). ((−1)ⁿ) est bornée et ne converge pas : être bornée ne suffit pas."),
 L("Valeur d'adhérence",`<p>ℓ est une <b>valeur d'adhérence</b> de (uₙ) s'il existe une sous-suite qui converge vers ℓ. Les valeurs d'adhérence de ((−1)ⁿ) sont 1 et −1.</p><p>Et si (u₂ₙ) et (u₂ₙ₊₁) tendent vers la <b>même</b> limite ℓ, alors uₙ → ℓ (TD 2, ex. 10c) : pour ε donné, on prend le plus grand des deux rangs.</p>`),
 Q("Quelles sont les valeurs d'adhérence de la suite uₙ = (−1)ⁿ + 1/n (pour n ≥ 1) ?",["1 et −1","0","1 seulement","Il n'y en a pas"],0,"Les termes de rang pair valent u₂ₙ = 1 + 1/(2n), qui tend vers 1 ; ceux de rang impair valent u₂ₙ₊₁ = −1 + 1/(2n + 1), qui tend vers −1. Une valeur d'adhérence est la limite d'une suite extraite : 1 et −1 en sont. Il n'y en a pas d'autre : une suite extraite a une infinité de termes pairs ou une infinité de termes impairs, donc elle ne peut tendre que vers 1 ou vers −1. 0 n'en est pas une : à part u₁ = 0, tous les termes vérifient |uₙ| ≥ 2/3, donc aucune suite extraite ne tend vers 0. Et « 1 seulement » oublie les termes impairs, qui sont aussi une suite extraite."),
 P("TD 2, exercice 2, sur papier",`<p>Donner un exemple pour chacune des situations suivantes :</p><p>(a) une suite décroissante positive qui ne converge pas vers 0</p><p>(b) une suite bornée non convergente</p><p>(c) une suite positive non bornée qui ne tend pas vers +∞</p><p>(d) une suite non monotone qui tend vers 0</p><p>(e) une suite positive qui tend vers 0 et qui n'est pas décroissante</p><p><b>Pour chaque exemple, justifie qu'il convient.</b> (Cette phrase n'est pas dans le TD, mais le corrigé officiel justifie chaque exemple.)</p>`,`<span class="who">Corrigé officiel (Moodle), recopié</span><p><b>(a)</b> uₙ = 1 + 1/n pour n ∈ ℕ*. C'est une suite décroissante, positive, qui converge vers 1 + 0 = 1, pas vers 0.</p><p><b>(b)</b> uₙ = (−1)ⁿ. Elle ne prend que les valeurs 1 et −1 : elle est bornée. Ses deux suites extraites sont constantes : u₂ₙ = 1 converge vers 1, et u₂ₙ₊₁ = −1 converge vers −1. Par l'absurde : si (uₙ) convergeait, ses suites extraites auraient la même limite ; ce n'est pas le cas.</p><p><b>(c)</b> uₙ = 0 si n est pair et uₙ = n si n est impair : (0, 1, 0, 3, 0, 5, 0, 7, …). Elle est positive. Elle n'est pas majorée : pour tout M ≥ 0, un entier impair n &gt; M donne uₙ = n &gt; M. Elle ne tend pas vers +∞ : sinon toute suite extraite tendrait vers +∞, or (u₂ₙ) est la suite nulle, qui converge vers 0.</p><p><b>(d)</b> uₙ = (−1)ⁿ/n pour n &gt; 0. Son signe alterne : elle n'est pas monotone. Pour tout n &gt; 0, −1/n ≤ uₙ ≤ 1/n, et −1/n et 1/n tendent vers 0 : par le théorème des gendarmes, uₙ → 0.</p><p><b>(e)</b> u₀ = 0 et uₙ = 1/n pour n &gt; 0. Elle est positive ; u₀ = 0 &lt; u₁ = 1, donc elle n'est pas décroissante ; et uₙ = 1/n → 0 (la limite ne dépend pas de u₀).</p><p>Remarque du corrigé : choisis ton exemple avec soin. Un exemple qui a l'air plus simple peut demander des preuves plus longues. D'autres exemples sont possibles : vérifie alors toi-même chaque propriété.</p>`,["Chaque exemple est donné par une formule précise (uₙ = …)","Chaque propriété demandée est justifiée, pas seulement affirmée","(b), (c) : une suite extraite sert à prouver « ne converge pas » ou « ne tend pas vers +∞ »","(d) : l'encadrement est écrit, et le théorème des gendarmes est cité"],12),
 K("Comment prouver qu'une suite n'a pas de limite, à l'aide de suites extraites ?","Trouver deux suites extraites (souvent u₂ₙ et u₂ₙ₊₁) qui ont des limites différentes."),
 K("Si les suites extraites (u₂ₙ) et (u₂ₙ₊₁) convergent vers la même limite ℓ, que peut-on dire de (uₙ) ? Et si leurs limites sont différentes ?","Alors uₙ → ℓ. Mais si leurs limites sont différentes, (uₙ) diverge.")]},

/* ------------------------------------------------------------------ */
{id:"a-lim-calc",t:"Limites de fonctions : calculs et pièges",min:15,p:2,goal:"Calculer des limites (conjuguée, identités remarquables) et montrer qu'une limite n'existe pas (TD 3, ex. 10 à 13).",steps:[
 Q("Quelle est la limite en 0 de la fonction f(x) = (√(1 + x) − √(1 − x))/x ?",["1","0","2","+∞"],0,"Avec la quantité conjuguée : 2x/(x(√(1 + x) + √(1 − x))) = 2/(√(1 + x) + √(1 − x)) → 2/2 = 1."),
 L("Les mêmes règles que pour les suites",`<p>Sommes, produits, quotients, valeur absolue : mêmes règles et mêmes formes indéterminées (+∞ − ∞, 0 × ∞, ∞/∞, 0/0) que pour les suites. On a aussi les <b>gendarmes</b> et le <b>passage à la limite</b> dans les inégalités (f ≤ g ⇒ lim f ≤ lim g ; avec f &lt; g, on garde seulement ≤).</p><p>Outils : quantité conjuguée (a − b)(a + b) = a² − b², et (a − b)(a² + ab + b²) = a³ − b³ pour les racines cubiques ; sin²x = 1 − cos²x = (1 − cos x)(1 + cos x).</p>`),
 Q("Quelle est la limite en π de la fonction f(x) = sin²x/(1 + cos x) ?",["2","0","1","Pas de limite"],0,"sin²x = (1 − cos x)(1 + cos x), donc le quotient vaut 1 − cos x → 1 − (−1) = 2 (TD 3, ex. 10b)."),
 S("Exemple corrigé : TD 3, exercice 10 (d)","L'énoncé : « Déterminer lim<sub>x→0</sub> (∛(1 + x²) − 1)/x². » Il ajoute : on pourra utiliser l'identité (a − b)(a² + ab + b²) = a³ − b³.",[
  {w:"C'est une forme indéterminée 0/0 : en 0, ∛(1 + x²) − 1 vaut 0, et x² aussi.",why:"∛ est la racine cubique : ∛8 = 2, car 2³ = 8. On vérifie d'abord qu'il y a une difficulté."},
  {w:"On pose a = ∛(1 + x²) et b = 1. Alors a³ − b³ = (1 + x²) − 1 = x².",why:"a³ = 1 + x² : le dénominateur x² apparaît tout seul."},
  {w:"L'identité donne : x² = a³ − 1 = (a − 1)(a² + a + 1).",why:"On remplace b par 1 dans (a − b)(a² + ab + b²)."},
  {w:"Donc, pour x ≠ 0 : (a − 1)/x² = (a − 1)/((a − 1)(a² + a + 1)) = 1/(a² + a + 1).",why:"Le facteur a − 1, celui qui s'annule en 0, se simplifie (a ≠ 1 quand x ≠ 0)."},
  {w:"Quand x → 0, a = ∛(1 + x²) → ∛1 = 1, donc a² + a + 1 → 3. La limite vaut 1/3.",why:"Il n'y a plus de forme indéterminée."}]),
 L("Limites et suites",`<p>Si lim<sub>x→x₀</sub> f(x) = ℓ et si une suite (xₙ) d'éléments de I tend vers x₀, alors f(xₙ) → ℓ.</p><p>D'où la méthode pour montrer qu'une limite <b>n'existe pas</b> : trouver <b>deux suites</b> xₙ → x₀ et yₙ → x₀ telles que f(xₙ) et f(yₙ) ont des limites différentes.</p><p>Exemple (TD 3, ex. 11) : sin(1/x) en 0. xₙ = 1/(2πn) → 0 donne sin(1/xₙ) = 0 ; yₙ = 1/(π/2 + 2πn) → 0 donne sin(1/yₙ) = 1. Pas de limite.</p><p>Attention : f(n) → L ne prouve pas que f(x) → L quand x → +∞ (sin(πx) vaut 0 en chaque entier, mais n'a pas de limite).</p>`),
 Q("La fonction f(x) = (x² + 2|x|)/x a-t-elle une limite en 0 ?",["Pas de limite : à droite elle tend vers 2, à gauche vers −2","Elle tend vers 0 : le numérateur tend vers 0","Elle tend vers 2 : on simplifie par x puis on prend x = 0","Elle tend vers +∞ : on divise par x, qui tend vers 0"],0,"x &gt; 0 : (x² + 2x)/x = x + 2 → 2. x &lt; 0 : (x² − 2x)/x = x − 2 → −2 (TD 3, ex. 10a). Simplifier par x en oubliant la valeur absolue ne marche que pour x &gt; 0."),
 Q("Deux fonctions f et g ont des limites finies en a, et f(x) &lt; g(x) pour tout x. A-t-on lim f &lt; lim g ?",["Non, seulement lim f ≤ lim g","Oui : l'inégalité stricte passe à la limite","Oui, dès que les deux limites sont finies"],0,"Contre-exemple : sur ]0, +∞[, f(x) = 0 et g(x) = x. On a bien f(x) &lt; g(x) pour tout x &gt; 0, mais en a = 0 les deux limites valent 0. Autre contre-exemple, en +∞ : f(x) = 0 &lt; g(x) = 1/(1 + x²), et les deux limites valent 0. Comme pour les suites, une inégalité stricte devient large à la limite (CC1 2025-2026, partie 2, question 1, réponse « faux »)."),
 P("TD 3, exercices 9, 13 et 14, sur papier",`<p><b>Exercice 9.</b> Déterminer <b>rigoureusement</b> lim<sub>x→+∞</sub> E(x)/x et lim<sub>x→+∞</sub> xE(1/x).</p><p><b>Exercice 13.</b> Déterminer la limite en +∞ de la fonction f : ℝ*₊ → ℝ définie par f(x) = cos(x)/√x.</p><p><b>Exercice 14.</b> La fonction x ↦ (x² + |x − 1| − 1)/(x − 1) admet-elle une limite épointée à droite ou à gauche quand x tend vers 1 ? Existe-t-il lim<sub>x→1, x≠1</sub> (x² + |x − 1| − 1)/(x − 1) ?</p>`,`<span class="who">Corrigé écrit par moi (pas de corrigé officiel)</span><p><b>Exercice 9.</b> Pour tout réel x : x − 1 &lt; E(x) ≤ x. Pour x &gt; 0, on divise par x : 1 − 1/x &lt; E(x)/x ≤ 1. Or 1 − 1/x tend vers 1 en +∞, et la fonction constante 1 aussi. Par le théorème d'encadrement, <b>lim<sub>x→+∞</sub> E(x)/x = 1</b>.<br>Soit x &gt; 1. Alors 0 &lt; 1/x &lt; 1, donc E(1/x) = 0, donc xE(1/x) = 0 : la fonction est nulle sur ]1, +∞[. Rigoureusement : soit ε &gt; 0 ; avec α = 1, pour tout x &gt; α, |xE(1/x) − 0| = 0 &lt; ε. Donc <b>lim<sub>x→+∞</sub> xE(1/x) = 0</b>.</p><p><b>Exercice 13.</b> Pour tout x &gt; 0, −1 ≤ cos(x) ≤ 1, donc −1/√x ≤ f(x) ≤ 1/√x. Or 1/√x et −1/√x tendent vers 0 en +∞. Par le théorème d'encadrement, <b>lim<sub>x→+∞</sub> f(x) = 0</b>. (cos(x) n'a pas de limite en +∞ : on ne peut pas écrire « limite de cos × limite de 1/√x ».)</p><p><b>Exercice 14.</b> Notons f cette fonction, définie pour x ≠ 1.<br>À droite (x &gt; 1) : |x − 1| = x − 1, donc le numérateur vaut x² + x − 2 = (x − 1)(x + 2), et f(x) = x + 2, qui tend vers 3. <b>La limite épointée à droite existe et vaut 3.</b><br>À gauche (x &lt; 1) : |x − 1| = 1 − x, donc le numérateur vaut x² − x = x(x − 1), et f(x) = x, qui tend vers 1. <b>La limite épointée à gauche existe et vaut 1.</b><br><b>La limite épointée en 1 n'existe pas</b> : si elle existait et valait ℓ, les limites épointées à droite et à gauche vaudraient toutes les deux ℓ. Or 3 ≠ 1.</p>`,["Ex. 9 : l'encadrement x − 1 &lt; E(x) ≤ x est écrit, puis le théorème d'encadrement est cité (c'est le « rigoureusement » de l'énoncé)","Ex. 9 : E(1/x) = 0 pour x &gt; 1, justifié par 0 &lt; 1/x &lt; 1","Ex. 13 : l'encadrement −1/√x ≤ f(x) ≤ 1/√x, et pas « limite de cos × limite de 1/√x »","Ex. 14 : les cas x &gt; 1 et x &lt; 1 sont séparés, et le numérateur est factorisé par x − 1","Ex. 14 : la conclusion « 3 ≠ 1, donc pas de limite épointée en 1 »"],15),
 K("Comment montrer qu'une fonction f n'a pas de limite en x₀ ?","Deux suites xₙ → x₀ et yₙ → x₀ avec f(xₙ) et f(yₙ) de limites différentes ; ou des limites à droite et à gauche différentes."),
 K("Quelles identités remarquables servent à lever une forme 0/0 qui contient des racines carrées ou cubiques ?","(a − b)(a + b) = a² − b² (racines carrées) ; (a − b)(a² + ab + b²) = a³ − b³ (racines cubiques).")]}
];
})();
